comms.text:
@1 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@2 מַלֵיל עִם בְּנֵי יִשְׂרָאֵל וְיַפְרְשׁוּן קֳדָמַי אַפְרָשׁוּתָא מִן כָּל גְבַר דִי יִתִּרְעֵי לִבֵּהּ תִּסְבוּן יָת אַפְרָשׁוּתִי:
@3 וְדָא אַפְרָשׁוּתָא דִתִסְבוּן מִנְהוֹן דַהֲבָא וְכַסְפָּא וּנְחָשָׁ א:
@4 וְתִכְלָא וְאַרְגְוָנָא וּצְבַע זְהוֹרִי וּבוּץ וּמֵעַזֵי:
@5 וּמַשְׁכֵי דְדִכְרֵי מְסַמְקֵי וּמַשְׁכֵי סַסְגוֹנָא וְאָעֵי שִׁטִין:
@6 מִשְׁחָא לְאַנְהָרוּתָא בּוּסְ מַיָא לְמִשְׁחָא דִרְבוּתָא וְלִקְטוֹרֶת בּוּסְמַיָא:
@7 אַבְנֵי בוּרְלָא וְאַבְנֵי אַשְׁלָמוּתָא לְשַׁקָעָא בְאֵפוֹדָא וּבְחוּשְׁנָא:
@8 וְיַעְבְּדוּן קֳדָמַי מִקְדְשָׁא וְאַשְׁרֵי שְׁכִנְתִּי בֵּינֵיהוֹן:
@9 כְּכֹל דִי אֲנָא מַחֲזֵי יָתָךְ יָת דְמוּת מַשְׁכְּנָא וְיָת דְמוּת כָּל מָנוֹהִי וְכֵן תַּעְבְּדוּן:
@10 וְיַעְבְּדוּן אֲרוֹנָא דְאָעֵי שִׁטִּין תַּרְתֵּין אַמִין וּפַלְגָא אֻרְכֵּהּ וְאַמְתָא וּפַלְגָא פְּתָיֵהּ וְאַמְתָא וּפַלְגָא רוּמֵה:
@11 וְתֶחֱפֵי יָתֵהּ דְהַב דְכֵי מִגָו וּמִבָּרָא תַּחֲפִנֵהּ וְתַעְבֵּד עֲלוֹהִי זֵיר דִדְהַב סְחוֹר סְחוֹר:
@12 וְתַתִּיךְ לֵהּ אַרְבַּע עִזְקָן דִדְהַב וְתִתֵּן עַל אַרְבַּע זִוְיָתֵהּ וְתַרְתֵּין עִזְקָן עַל סִטְרֵהּ חַד וְתַרְתֵּן עִזְקָן עַל סִטְרֵהּ תִּנְיֵתָא:
@13 וְתַעְבֵּד אֲרִיחֵי דְאָעֵי שִׁטִּין וְתַחֲפֵי יָתְהוֹן דַהֲבָא:
@14 וְתָעֵל יָת אֲרִיחֲיָא בְּעִזְקָתָא עַל סִטְרֵי אֲרוֹנָא לְמִטַל יָת אֲרוֹנָא בְּהוֹן:
@15 בְּעִזְקְתָא דַאֲרוֹנָא יְהוֹן אֲרִיחַיָא לָא יְעִדוּן מִנֵהּ:
@16 וְתִתֵּן בַּאֲרוֹנָא יָת סַהֲדוּתָא דִי אֶתֵּן לָךְ:
@17 וְתַעְבֵּד כַּפֻּרְתָּא דִדְהַב דְכֵי תַּרְתֵּין אַמִין וּפַלְגָא אֻרְכַּהּ וְאַמְתָא וּפַלְגָא פְּתָיַהּ:
@18 וְתַעְבֵּד תְּרֵין כְּרוּבִין דִדְהָב נְגִיד תַּעְבֵּד יָתְהוֹן מִתְּרֵין סִטְרֵי כַפֻּרְתָּא:
@19 וְעִבֵּד כְּרוּבָא חַד מִסִטְרָא מִכָּא וּכְרוּבָא חַד מִסִטְרָא מִכָּא מִן כַּפֻּרְתָּא תַּעְבְּדוּן יָת כְּרוּבַיָא עַל תְּרֵין סִטְרוֹהִי:
@20 וִיהוֹן כְּרוּבַיָא פְּרִיסָן גַדְפֵיהוֹן לְעֵלָא מְטַלִין בְּגַדְפֵהוֹן עַל כַּפֻּרְתָּא וְאַפֵּיהוֹן חַד לָקֳבֵל חַד לָקֳבֵל כַּפֻּרְתָּא יְהוֹן אַפֵי כְרוּבַיָא:
@21 וְתִתֵּן יָת כַּפֻּרְתָּא עַל אֲרוֹנָא מִלְעֵלָא וּבַאֲרוֹנָא תִּתֵּן יָת סַהֲדוּתָא דִי אֶתֵּן לָךְ:
@22 וֶאֱזַמֵן מֵימְרִי לָךְ תַּמָן וֶאֱמַלֵל עִמָךְ מֵעִלָוֵי כַפֻּרְתָּא מִבֵּין תְּרֵין כְּרוּבַיָא דִי עַל אֲרוֹנָא דְסַהֲדוּתָא יָת כָּל דִי אֲפַקֵד יָתָךְ לְוָת בְּנֵי יִשְׂרָאֵל:
@23 וְתַעְבֵּד פָּתוֹרָא דְאָעֵי שִׁטִּין תַּרְתֵּין אַמִין אֻרְכֵּהּ וְאַמְתָא פְתָיֵהּ וְאַמְתָא וּפַלְגָא רוּמֵהּ:
@24 וְתַחֲפֵי יָתֵהּ דְהַב דְכֵי וְתַעְבֵּד לֵהּ זֵיר דִדְהַב סְחוֹר סְחוֹר:
@25 וְתַעְבֵּד לֵהּ גְדַנְפָא רוּמֵהּ פֻּשְׁכָּא סְחוֹר סְחוֹר וְתַעְבֵּד זֵיר דִדְהַב לִגְדַנְפֵהּ סְחוֹר סְחוֹר:
@26 וְתַעְבֵּד לֵהּ אַרְבַּע עִזְקָן דִדְהָב וְתִתֵּן יָת עִזְקָתָא עַל אַרְבַּע זִיוְיָתָא דִי לְאַרְבַּע רַגְלוֹהִי:
@27 לָקֳבֵל גְדַנְפָא יְהֶוְיָן עִזְקָתָא לְאַתְרָא לַאֲרִיחַיָא לְמִטַל יָת פָּתוֹרָא:
@28 וְתַעְבֵּד יָת אֲרִיחַיָא דְאָעֵי שִׁיטִין וְתַחֲפֵי יָתְהוֹן דַהֲבָא וִיהוֹן נָטְלִין בְּהוֹן יָת פָּתוֹרָא:
@29 וְתַעְבֵּד מָגִיסוֹהִי וּבָזִכּוֹהִי וְקַסְוָתֵהּ וּמְכִילָתֵהּ דְיִתְנַסַךְ בְּהֵן דְהַב דְכֵי תַּעְבֵּד יָתְהוֹן:
@30 וְתִתֵּן עַל פָּתוֹרָא לְחֵם אַפַּיָא קֳדָמַי תְּדִירָא:
@31 וְתַעְבֵּד מְנַרְתָּא דִדְהַב דְכֵי נְגִיד תִּתְעֲבֵד מְנַרְתָּא שִׁדַהּ וּקְנַהּ כַּלִידָהָא חֵזוּרָהָא וְשׁוֹשַׁנָהָא מִנַהּ יְהוֹן:
@32 וְשִׁתָּא קְנִין נָפְקִין מִסִטְרָהָא תְּלָתָא קְנֵי מְנַרְתָּא מִסִטְרַהּ חַד וּתְלָתָא קְנֵי מְנַרְתָּא מִסִטְרַהּ תִּנְיָנָא:
@33 תְּלָתָא כַלִידִין מְצַיְרִין בְּקַנְיָא חַד חֵזוּר וְשׁוֹשַׁן וּתְלָתָא כַלִידִין מְצַיְרִין בְּקַנְיָא חַד חֵזוּר וְשׁוֹשָׁן כֵּן לְשִׁתָּא קְנִין דְנָפְקִין מִן מְנַרְתָּא:
@34 וּבִמְנַרְתָּא אַרְבְּעָא כַלִידִין מְצַיְרִין חֵזוּרָהָא וְשׁוֹשַׁנָהָא:
@35 וְחֵזוּר תְּחוֹת תְּרֵין קְנִין מִנַהּ וְחֵזוּר תְּחוֹת תְּרֵין קְנִין מִנַהּ וְחֵזוּר תְּחוֹת תְּרֵין קְנִין מִנַהּ לְשִׁתָּא קְנִין דְנָפְקִין מִן מְנַרְתָּא:
@36 חֵזוּרֵיהוֹן וּקְנֵיהוֹן מִנַהּ יְהוֹן כֻּלַהּ נְגִידָא חֲדָא דִדְהַב דְכֵי:
@37 וְתַעְבֵּד יָת בּוֹצִינָהָא שִׁבְעָא וְתַדְלֵק יָת בּוֹצִינָהָא וִיהוֹן מְנַהֲרִין עַל קֳבֵל אַפָּהָא:
@38 וְצִבְיְתָהָא וּמַחְתְּיָתָהָא דִדְהַב דְכֵי:
@39 כִּכְּרָא דִדְהַב דְכֵי יַעְבֵּד יָתַהּ יָת כָּל מָנַיָא הָאִלֵין:
@40 וַחֲזֵי וַעֲבֵיד כִּדְמוּתְהוֹן דִאַתְּ מִתְחֲזִי בְּטוּרָא:
@41 וְיָת מַשְׁכְּנָא תַּעְבֵּד עֲשַׂר יְרִיעָן דְבוּץ שְׁזִיר וְתִכְלָא וְאַרְגְּוָנָא וּצְבַע זְהוֹרִי צוּרַת כְּרוּבִין עוֹבַד אֳמָן תַּעְבֵּד יָתְהוֹן:
@42 אֻרְכָּא דִירִיעֲתָא חֲדָא עַשְׂרִין וְתַמְנֵי אַמִין וּפוּתְיָא אַרְבַּע אַמִין דִירִיעֲתָא חֲדָא מְשַׁחְתָּא חֲדָא לְכָל יְרִיעֲתָא:
@43 חֲמֵשׁ יְרִיעָן יְהֶוְיָן מְלַפְּפָן חֲדָא עִם חֲדָא וַחֲמֵשׁ יְרִיעָן מְלַפְּפָן חֲדָא עִם חֲדָא:
@44 וְתַעְבֵּד עֲנוּבִין דְתִכְלָא עַל שִׂפְתָא דִירִיעֲתָא חֲדָא מִסִטְרָא בֵּית לוֹפֵי וְכֵן תַּעְבֵּד בְּשִׂפְתָא דִירִיעֲתָא בְּסִטְרָא דְבֵית לוֹפֵי תִּנְיֵתָא:
@45 חַמְשִׁין עֲנוּבִין תַּעְבֵּד בִּירִיעֲתָא חֲדָא וְחַמְשִׁין עֲנוּבִין תַּעְבֵּד בְּסִטְרָא דִירִיעֲתָא דְבֵית לוֹפֵי תִּנְיָנָא מְכַוְנָן עֲנוּבַיָא חֲדָא לָקֳבֵל חֲדָא:
@46 וְתַעְבֵּד חַמְשִׁין פּוּרְפִין דִדְהָב וּתְלָפֵף יָת יְרִיעֲתָא חֲדָא עִם חֲדָא בְּפּוּרְפַיָא וִיהֵי מַשְׁכְּנָא חָד:
@47 וְתַעְבֵּד יְרִיעָן מְעַזֵי לִפְרָסָא עַל מַשְׁכְּנָא חֲדָא עֶסְרֵי יְרִיעָן תַּעְבֵּד יָתְהוֹן:
@48 אֻרְכָּא דִירִיעֲתָא חֲדָא תְּלָתִין אַמִין וּפוּתְיָא אַרְבַּע אַמִין דִירִיעֲתָא חֲדָא מְשַׁחְתָּא חֲדָא לַחֲדָא עֶסְרֵי יְרִיעָן:
@49 וּתְלָפֵף יָת חֲמֵשׁ יְרִיעָן לְחוֹד וְיָת שִׁית יְרִיעָן לְחוֹד וְתֵיעוּף יָת יְרִיעֲתָא שְׁתִיתֵיתָא לָקֳבֵל אַפֵּי מַשְׁכְּנָא:
@50 וְתַעְבֵּד חַמְשִׁין עֲנוּבִין עַל שִׂפְתָא דִירִיעֲתָא חֲדָא בְּסִטְּרָא בֵּית לוֹפֵי וְחַמְשִׁין עֲנוּבִין עַל שִׂפְתָא דִירִיעֲתָא דְבֵית לוֹפֵי תִּנְיֵתָא:
@51 וְתַעְבֵּד פּוּרְפִין דִנְחָשָׁא חַמְשִׁין וְתָעֵיל יָת פּוּרְפַיָא בַּעֲנוּבַיָא וּתְלָפֵף יָת מַשְׁכְּנָא וִיהֵי חָד:
@52 וְסִרְחָא דְיַתִּירָא בִּירִיעַת מַשְׁכְּנָא פַּלְגוּת יְרִיעֲתָא דְיַתִּירָא תִּסְרַח עַל אֲחוֹרֵי מַשְׁכְּנָא:
@53 וְאַמְתָא מִכָּא וְאַמְתָא מִכָּא בִּדְיַתִּירָא בְּאֻרְכָּא יְרִיעֲתָא דְמַשְׁכְּנָא יְהֵי סְרִיחַ עַל סִטְרֵי מַשְׁכְּנָא מִכָּא וּמִכָּא לְכַסָיוּתֵהּ:
@54 וְתַעְבֵּד חוֹפָאָה לִפְרָסָא מַשְׁכֵי דְדִכְרֵי מְסַמְקֵי וְחוֹפָאָה מַשְׁכֵי דְסַסְגוֹנָא מִלְעֵלָא:
@55 וְתַעְבֵּד יָת דַפַּיָא לְמַשְׁכְּנָא דְאָעֵי שִטִין קָיְמִין:
@56 עֲשַׂר אַמִין אֻרְכָּא דְדַפָּא וְאַמְתָא וּפַלְגוּת אַמְתָא פּוּתְיָא דְדַפָּא חָד:
@57 תַּרְתֵּין צִירִין לְדַפָּא חַד מְשַׁלְבִין חֲדָא לָקֳבֵל חֲדָא כֵּן תַּעְבֵּד לְכֹל דַפֵּי מַשְׁכְּנָא:
@58 וְתַעְבֵּד יָת דַפַּיָא לְמַשְׁכְּנָא עַסְרִין דַפִּין לְרוּחַ עֵבַר דְרוֹמָא:
@59 וְאַרְבְּעִין סַמְכִין דִכְסַף תַּעְבֵּד תְּחוֹת עַסְרִין דַפִּין תְּרֵין סַמְכִין תְּחוֹת דַפָּא חַד לִתְרֵין צִירוֹהִי וּתְרֵין סַמְכִין תְּחוֹת דַפָּא חַד לִתְרֵין צִירוֹהִי:
@60 וְלִסְטַר מַשְׁכְּנָא תִּנְיֵתָא לְרוּחַ צִפּוּנָא עֶסְרִין דַפִּין:
@61 וְאַרְבְּעִין סַמְכֵיהוֹן דִכְסַף תְּרֵין סַמְכִין תְּחוֹת דַפָּא חַד וּתְרֵין סַמְכִין תְּחוֹת דַפָּא חָד:
@62 וְלִסְיָפֵי מַשְׁכְּנָא מַעַרְבָא תַּעְבֵּד שִׁתָּא דַפִּין:
@63 וּתְרֵין דַפִּין תַּעְבֵּד לְזָוְיַת מַשְׁכְּנָא בְּסוֹפֵיהוֹן:
@64 וִיהוֹן מְכַוְנִין מִלְרַע וְכַחֲדָא יְהוֹן מְכַוְנִין עַל רֵישֵׁהּ לְעִזְקְתָא חֲדָא כֵּן יְהֵי לְתַרְוֵיהוֹן לִתְרֵין זָוְיָן יְהוֹן:
@65 וִיהוֹן תְּמַנְיָא דַפִּין וְסַמְכֵיהוֹן דִכְסַף שִׁתָּא עֲשַׂר סַמְכִין תְּרֵין סַמְכִין תְּחוֹת דַפָּא חַד וּתְרֵין סַמְכִין תְּחוֹת דַפָּא חָד:
@66 וְתַעְבֵּד עַבְּרֵי דְאָעֵי שִׁטִין חַמְשָׁא לְדַפֵּי סְטַּר מַשְׁכְּנָא חָד:
@67 וְחַמְשָׁא עַבְּרִין לְדַפֵּי סְטַר מַשְׁכְּנָא תִּנְיֵתָא וְחַמְשָׁא עַבְּרִין לְדַפֵּי סְטַּר מַשְׁכְּנָא לְסוֹפֵיהוֹן מַעַרְבָא:
@68 וְעַבְּרָא מְצִיעָאָה בְּגוֹ דַפַּיָא מַעְבַר מִן סְיָפֵי לִסְיָפֵי:
@69 וְיָת דַפַּיָא תַּחְפֵּי דַהֲבָא וְיָת עִזְקָתְהוֹן תַּעְבֵּד דַהֲבָא אַתְרָא לְעַבְרַיָא וְתַחְפֵּי יָת עַבְּרַיָא דַהֲבָא:
@70 וּתְקִים יָת מַשְׁכְּנָא כְּהִלְכְתֵהּ דִי אִתְחֲזֵיתָא בְּטוּרָא:
@71 וְתַעְבֵּד פָּרֻכְתָּא תִּכְלָא וְאַרְגְוָנָא וּצְבַע זְהוֹרִי וּבוּץ שְׁזִיר עוֹבַד אֳמָן יַעְבֵּד יָתַהּ צוּרַת כְּרוּבִין:
@72 וְתִתֵּן יָתַהּ עַל אַרְבְּעָא עַמוּדֵי שִׁטִין מְחַפְּיָן דַהֲבָא וָוֵיהוֹן דַהֲבָא עַל אַרְבְּעָא סַמְכֵי דִכְסָף:
@73 וְתִתֵּן יָת פָּרֻכְתָּא תְּחוֹת פּוּרְפַיָא וְתָעֵיל תַּמָן מִגָּו לְפָרֻכְתָּא יָת אֲרוֹנָא דְסַהֲדוּתָא וְתַפְרֵשׁ פָּרֻכְתָּא לְכוֹן בֵּין קוּדְשָׁא וּבֵין קֹדֶשׁ קוּדְשַׁיָא:
@74 וְתִתֵּן יָת כַּפֻּרְתָּא עַל אֲרוֹנָא דְסַהֲדוּתָא בְּקֹדֶשׁ קוּדְשַׁיָא:
@75 וּתְשַׁוִי יָת פָּתוֹרָא מִבָּרָא לְפָרֻכְתָּא וְיָת מְנַרְתָּא לָקֳבֵל פָּתוֹרָא עַל צִדָּא דְמַשְּׁכְּנָא דָרוֹמָא וּפָתוֹרָא תִתֵּן עַל סְטַר צִפּוּנָא:
@76 וְתַעְבֵּד פְּרָסָא לִתְרַע מַשְׁכְּנָא תִּכְלָא וְאַרְגְוָנָא וּצְבַע זְהוֹרִי וּבוּץ שְׁזִיר עוֹבַד צַיָר:
@77 וְתַעְבֵּד לִפְרָסָא חַמְשָׁא עַמוּדֵי שִׁטִין וְתַחֲפֵי יָתְהוֹן דַהֲבָא וָוֵיהוֹן דַהֲבָא וְתַתִּיךְ לְהוֹן חַמְשָׁא סַמְכֵי נְחָשָׁא:
@78 וְתַעְבֵּד יָת מַדְבְּחָא דְאָעֵי שִׁטִין חֲמֵשׁ אַמִין אֻרְכָּא וַחֲמֵשׁ אַמִין פּוּתְיָא מְרַבַּע יְהֵי מַדְבְּחָא וּתְלַת אַמִין רוּמֵהּ:
@79 וְתַעְבֵּד קַרְנוֹהִי עַל אַרְבַּע זִוְיָתֵהּ מִנֵהּ תְּהֶוְיָן קַרְנוֹהִי וְתַחֲפֵי יָתֵהּ נְחָשָׁא:
@80 וְתַעְבֵּד פְּסַכְתְּרָוָתֵהּ לְמִסְפֵי קִטְּמֵיהּ וּמַגְרוֹפְיָתֵהּ וּמִזְרְקָתֵהּ וְצִנוּרְיָתֵהּ וּמַחְתְּיָתֵהּ לְכָל מָנוֹהִי תַּעְבֵּד נְחָשָׁא:
@81 וְתַעְבֵּד לֵהּ סְרָדָא עוֹבַד מְצַדְתָּא דִנְחָשָׁא וְתַעְבֵּד עַל מְצַדְתָּא אַרְבַּע עִזְקָן דִנְחָשָׁא עַל אַרְבַּע סִטְּרוֹהִי:
@82 וְתִתֵּן יָתַהּ תְּחוֹת סוֹבָבֵי מַדְבְּחָא מִלְרָע וּתְהֵי מְצַדְתָּא עַד פַּלְגוּת מַדְבְּחָא:
@83 וְתַעְבֵּד אֲרִיחַיָא לְמַדְבְּחָא אֲרִיחֵי דְאָעֵי שִׁטִין וְתַחֲפֵי יָתְהוֹן נְחָשָׁא:
@84 וְיָעֵל יָת אֲרִיחוֹהִי בְּעִזְקָתָא וִיהוֹן אֲרִיחַיָא עַל תְּרֵין סִטְרֵי מַדְבְּחָא בְּמִטַל יָתֵהּ:
@85 חֲלִיל לוּחֵי תַּעְבֵּד יָתֵהּ כְּמָא דִי אַחֲזִי יָתָךְ בְּטוּרָא כֵּן יַעְבְּדוּן:
@86 וְתַעְבֵּד יָת דָרַת מַשְׁכְּנָא לְרוּחַ עֵבַר דָרוֹמָא סְרָדִין לְדָרְתָּא דְבוּץ שְׁזִיר מְאָה בְאַמִין אֻרְכָּא לְעֵבֶר חָד:
@87 וְעַמוּדוֹהִי עֶשְׂרִין וְסַמְכֵיהוֹן עֶשְׂרִין נְחָשָׁא וָוֵי עַמוּדַיָא וְכִבּוּשֵׁיהוֹן כְּסָף:
@88 וְכֵן לְרוּחַ צִפּוּנָא בְּאֻרְכָּא סְרָדִין מְאָה אֻרְכָּא וְעַמוּדוֹהִי עֶשְׂרִין וְסַמְכֵיהוֹן עֶשְׂרִין נְחָשָׁא וָוֵי עַמוּדַיָא וְכִבּוּשֵׁהוֹן דִכְסָף:
@89 וּפוּתְיָא דְדַרְתָּא לְרוּחַ מַעַרְבָא סְרָדִין חַמְשִׁין אַמִין עַמוּדֵיהוֹן עַשְׂרָא וְסַמְכֵיהוֹן עַשְׂרָא:
@90 וּפוּתְיָא דְדַרְתָּא לְרוּחַ קִדוּמָא מַדִינְחָא חַמְשִׁין אַמִין:
@91 וַחֲמֵשׁ עֶשְׂרֵי אַמִין סְרָדִין לְעִבְרָא עַמוּדֵיהוֹן תְּלָתָא וְסַמְכֵיהוֹן תְּלָתָא:
@92 וּלְעִבְרָא תִּנְיָנָא חֲמֵשׁ עֶשְׂרֵי סְרָדִין עֲמוּדֵיהוֹן תְּלָתָא וְסַמְכֵיהוֹן תְּלָתָא:
@93 וְלִתְרַע דַרְתָּא פְּרָסָא עֶשְׂרִין אַמִין תִּכְלָא וְאַרְגְוָנָא וּצְבַע זְהוֹרִי וּבוּץ שְׁזִיר עוֹבַד צַיָר עַמוּדֵיהוֹן אַרְבְּעָא וְסַמְכֵיהוֹן אַרְבְּעָא:
@94 כָּל עַמוּדֵי דַרְתָּא סְחוֹר סְחוֹר מְכַבְּשִׁין כְּסַף וָוֵיהוֹן כְּסַף וְסַמְכֵיהוֹן נְחָשָׁא:
@95 אֻרְכָּא דְדַרְתָּא מְאָהּ בְאַמִין וּפוּתְיָא חַמְשִׁין בְּחַמְשִׁין וְרוּמָא חֲמֵשׁ אַמִין דְבוּץ שְׁזִיר וְסַמְכֵיהוֹן נְחָשָׁא:
@96 לְכֹל מָאנֵי מַשְׁכְּנָא בְּכֹל פָּלְחָנֵהּ וְכָל סִכּוֹהִי וְכָל סִכֵּי דְדַרְתָּא נְחָשָׁא:ססס:

@2 **ויקחו לי תרומה.** לי לשמי: **תרומה.** הפרשה, יפרישו לי מממונם נדבה: **ידבנו לבו.** לשון נדבה, והוא לשון רצון טוב, פרישנ''ט בלעז : **תקחו את תרומתי.** אמרו רבותינו שלש תרומות אמורות כאן, אחת תרומת בקע לגלגלת, שנעשו מהם האדנים, כמו שמפורש באלה פקודי (שמות לח כו. כז) , ואחת תרומת המזבח בקע לגלגלת לקפות לקנות מהן קרבנות צבור, ואחת תרומת המשכן נדבת כל אחד ואחד. שלשה עשר דברים האמורים בענין כלם הצרכו למלאכת המשכן או לבגדי כהנה, כשתדקדק בהם:
@3 **זהב וכסף ונחשת** וגו' **.** כלם באו בנדבה, איש איש מה שנדבו לבו, חוץ מן הכסף שבא בשוה מחצית השקל לכל אחד, ולא מצינו בכל מלאכת המשכן, שהצרך שם כסף יותר, שנאמר (שמות לח כו, כז) וכסף פקודי העדה וגו' בקע לגלגלת וגו' , ושאר הכסף הבא שם בנדבה עשאוה לכלי שרת:
@4 **ותכלת.** צמר צבוע בדם חלזון, וצבעו ירוק: **וארגמן.** צמר צבוע ממין צבע ששמו ארגמן: **ושש.** הוא פשתן: **ועזים.** נוצה של עזים, לכך תרגם אנקלוס ומעזי, הבא מן העזים, ולא עזים עצמם, שתרגום של עזים עזיא:
@5 **מאדמים.** צבועות היו אדום לאחר עבודן: **תחשים.** מין חיה, ולא היתה אלא לשעה והרבה גונים היו לה, לכך מתרגם ססגונא, ששש ומתפאר בגונין שלו: **ועצי שטים.** מאין היו להם במדבר, פרש רבי תנחומא יעקב אבינו צפה ברוח הקדש, שעתידין ישראל לבנות משכן במדבר, והביא ארזים למצרים ונטעם, וצוה לבניו לטלם עמהם, כשיצאו ממצרים:
@6 **שמן למאור.** שמן זית זך להעלות נר תמיד: **בשמים לשמן המשחה.** שנעשה למשוח כלי המשכן והמשכן לקדשו, והצרכו לו בשמים כמו שמפורש בכי תשא (שמות ל כג. כה) : **ולקטרת הסמים.** שהיו מקטירין בכל ערב ובקר, כמו שמפורש בואתה תצוה (שמות ל ז. ח) ולשון קטרת העלאת קיטור ותמרות עשן:
@7 **אבני שהם.** שתים הצרכו שם לצורך האפוד האמור בואתה תצוה (שמות כח יב) : **מלאים.** על שם שעושין להם בזהב מושב כמין גמא ונותנין האבן שם למלאות הגמא, קרויים אבני מלאים, ומקום המושב קרוי משבצות: **לאפוד ולחשן.** אבני השהם לאפוד, ואבני המלאים לחשן, וחשן ואפוד מפורשים בואתה תצוה, והם מיני תכשיט:
@8 **ועשו לי מקדש.** ועשו לשמי בית קדשה:
@9 **ככל אשר אני מראה אותך.** כאן את תבנית המשכן. המקרא הזה מחבר למקרא שלמעלה המנו ועשו לי מקדש ככל אשר אני מראה אותך: **וכן תעשו.** לדורות אם יאבד אחד מן הכלים או כשתעשו לי כלי בית עולמים, כגון שלחנות ומנורות וכיורות ומכונות שעשה שלמה, כתבנית אלו תעשו אותם. ואם לא היה המקרא מחבר למעלה המנו, לא היה לו לכתוב וכן תעשו אלא כן תעשו, והיה מדבר על עשית אהל מועד וכליו:
@10 **ועשו ארון.** כמין ארונות שעושים בלא רגלים, עשוים כמין ארגז שקורין אישקרי''ן בלעז , יושב על שוליו:
@11 **מבית ומחוץ תצפנו.** שלשה ארונות עשה בצלאל, שתים של זהב ואחד של עץ, וארבע כתלים ושולים לכל אחד ופתוחים מלמעלה, נתן של עץ בתוך של זהב ושל זהב בתוך של עץ, וחפה שפתו העליונה בזהב, נמצא מצפה מבית ומחוץ: **זר זהב.** כמין כתר מקיף לו סביב למעלה משפתו, שעשה הארון החיצון גבוה מן הפנימי עד שעלה למול עובי הכפורת ולמעלה המנו משהו, וכשהכפורת שוכב על עובי הכתלים, עולה הזר למעלה מכל עובי הכפורת כל שהוא, והוא סימן לכתר תורה:
@12 **ויצקת.** לשון התכה כתרגומו: **פעמתיו.** כתרגומו זויתיה. ובזויות העליונות סמוך לכפרת היו נתונות שתים מכאן ושתים מכאן לרחבו של ארון, והבדים נתונים בהם, וארכו של ארון מפסיק בין הבדים, אמתים וחצי בין בד לבד, שיהיו שני בני אדם, הנושאים את הארון, מהלכין ביניהם, וכן מפורש במנחות בפרק שתי הלחם (צח ב) **ושתי טבעות על צלעו האחת.** הן הן הארבע טבעות שבתחלת המקרא, ופרש לך היכן היו, והוי''ו זו יתרה היא ופתרונו כמו שתי טבעות, ויש לך לישבה כן ושתים מן הטבעות האלו על צלעו האחת: **צלעו.** צדו:
@13 **בדי.** מוטות:
@15 **לא יסרו ממנו.** לעולם:
@16 **ונתת אל הארן.** כמו בארון: **העדות.** התורה שהיא לעדות ביני וביניכם, שצויתי אתכם מצות הכתובות בה:
@17 **כפרת.** כסוי על הארון שהיה פתוח מלמעלה ומניחו עליו כמין דף: **אמתים וחצי ארכה.** כארכו של ארון, ורחבה כרחבו של ארון, ומנחת על עובי הכתלים ארבעתם, ואף על פי שלא נתן שעור לעביה, פרשו רבותינו שהיה עביה טפח:
@18 **כרבים.** דמות פרצוף תינוק להם: **מקשה תעשה אתם.** שלא תעשם בפני עצמם ותחברם בראשי הכפרת לאחר עשיתם כמעשה צורפים, שקורין שולדי''ץ [מלחמים] אלא הטל זהב הרבה בתחלת עשית הכפרת והכה בפטיש ובקרנס באמצע, וראשין בולטין למעלה וצייר הכרובים בבליטת קצותיו: **מקשה.** בטידי''ץ בלעז [עשוי בהכאה] . כמו (דניאל ה ו) דא לדא נקשן: **קצות הכפורת.** ראשי הכפרת:
@19 **ועשה כרוב אחד מקצה.** שלא תאמר שנים כרובים לכל קצה וקצה, לכך הצרך לפרש כרוב אחד מקצה מזה: **מן הכפרת.** עצמה תעשו את הכרובים. זהו פרושו של מקשה תעשה אותם, שלא תעשם בפני עצמם ותחברם לכפרת:
@20 **פרשי כנפים.** שלא תעשה כנפיהם שוכבים, אלא פרושים וגבוהים למעלה אצל ראשיהם, שיהא עשרה טפחים בחלל בין הכנפים לכפרת, כדאיתא בסכה (דף ה ב) :
@21 **ואל הארן תתן את העדות.** לא ידעתי למה נכפל, שהרי כבר נאמר (פסוק טז) ונתת אל הארון את העדות. ויש לומר שבא ללמד, שבעודו ארון לבדו בלא כפרת, יתן תחלה העדות לתוכו, ואחר כך יתן את הכפרת עליו. וכן מצינו כשהקים את המשכן נאמר (שמות מ כ) ויתן את העדות אל הארון, ואחר כך ויתן את הכפורת על הארון מלמעלה:
@22 **ונועדתי.** כשאקבע מועד לך לדבר עמך, אותו מקום אקבע למועד שאבא שם לדבר אליך: **ודברתי אתך מעל הכפורת.** ובמקום אחר הוא אומר (ויקרא א א) וידבר ה' אליו מאהל מועד לאמר, זה המשכן מחוץ לפרכת, נמצאו שני כתובים מכחישים זה את זה, בא הכתוב השלישי והכריע ביניהם (במדבר ז פט) ובבא משה אל אהל מועד וישמע את הקול מדבר אליו מעל הכפרת וגו' , משה היה נכנס למשכן וכיון שבא בתוך הפתח, קול יורד מן השמים לבין הכרובים, ומשם יוצא ונשמע למשה באהל מועד: **ואת כל אשר אצוה אותך אל בני ישראל.** הרי וי''ו זו יתרה וטפלה, וכמוהו הרבה במקרא, וכה תפתר ואת אשר אדבר עמך שם, את כל אשר אצוה אותך אל בני ישראל הוא.
@23 **קמתו.** גובה רגליו עם עובי השלחן:
@24 **זר זהב.** סימן לכתר מלכות, שהשלחן שם עושר וגדלה, כמו שאומרים שלחן מלכים:
@25 **מסגרת.** כתרגומו גדנפא, ונחלקו חכמי ישראל בדבר יש אומרים, למעלה היתה סביב לשלחן, כמו לבזבזין שבשפת שלחן שרים, ויש אומרים, למטה היתה תקועה מרגל לרגל בארבע רוחות השלחן, ודף השלחן שוכב על אותה מסגרת: **ועשית זר זהב למסגרתו.** הוא זר האמור למעלה, ופרש לך כאן שעל המסגרת היתה:
@27 **לעמת המסגרת תהיין הטבעות.** ברגלים תקועות כנגד ראשי המסגרת: **לבתים לבדים.** אותן הטבעות יהיו בתים להכניס בהן הבדים: **לבתים.** לצורך בתים: **לבדים.** כתרגומו אתרא לאריחיא:
@28 **ונשא בם.** לשון נפעל, יהיה נשא בם את השלחן:
@29 **ועשית קערתיו וכפתיו.** קערותיו זה הדפוס שהיה עשוי כדפוס הלחם, והלחם היה עשוי כמין תבה פרוצה משתי רוחותיה, שולים לו למטה וקופל מכאן ומכאן כלפי מעלה כמין כתלים, ולכך קרוי לחם הפנים, שיש לו פנים רואין לכאן ולכאן לצדי הבית מזה ומזה, ונותן ארכו לרחבו של שלחן, וכתליו זקופים כנגד שפת השלחן, והיה עשוי לו דפוס זהב ודפוס ברזל, בשל ברזל הוא נאפה וכשמוציאו מן התנור נותנו בשל זהב עד למחר בשבת שמסדרו על השלחן, ואותו הדפוס קרוי קערה: **וכפתיו.** בזכין שנותנים בהם לבונה, ושתים היו לשני קמצי לבונה שנותנין על שתי המערכות, שנאמר (ויקרא כד ז) ונתת על המערכת לבונה זכה: **וקשותיו.** הן כמין חצאי קנים חלולים הנסדקין לארכן דגמתן עשה של זהב ומסדר שלשה על ראש כל לחם, שישב לחם האחד על גבי אותן הקנים ומבדילין בין לחם ללחם כדי שתכנס הרוח ביניהם ולא יתעפשו, ובלשון ערבי כל דבר חלול קרוי קסו''ה: **ומנקיתיו.** תרגומו ומכילתיה, הן סניפים, כמין יתדות זהב עומדין בארץ וגבוהים עד למעלה מן השלחן הרבה כנגד גובה מערכת הלחם, ומפצלים ששה פצולים זה למעלה מזה, וראשי הקנים שבין לחם ללחם סמוכין על אותן פצולין, כדי שלא יכבד משא הלחם העליונים על התחתונים וישברו ולשון מכילתיה, סובלותיו, כמו (ירמיה ו יא) נלאיתי הכיל, אבל לשון מנקיות איני יודע, איך נופל על סניפין. ויש מחכמי ישראל אומרים קשותיו אלו סניפין, שמקשין אותו ומחזיקין אותו שלא ישבר, ומנקיותיו אלו הקנים שמנקין אותו שלא יתעפש, אבל אונקלוס שתרגם ומכילתיה היה שונה כדברי האומר מנקיות הן סניפין: **אשר יסך בהן.** אשר יכסה בהן, ועל קשותיו הוא אומר אשר יסך, שהיו עליו כמין סכך וכסוי, וכן במקום אחר הוא אומר (במדבר ד ז) ואת קשות הנסך וזה וזה, יסך והנסך, לשון סכך וכסוי הם:
@30 **לחם פנים.** שיש לו פנים כמו שפרשתי, ומנין הלחם וסדר מערכותיו מפורשים באמור אל הכהנים:
@31 **מקשה תעשה המנורה.** שלא יעשנה חליות, ולא יעשה קניה ונרותיה איברים איברים, ואחר כך ידביקם כדרך הצורפין, שקורין שולדי''ר בלעז אלא כלה באה מחתיכה אחת, ומקיש בקרנס וחותך בכלי האמנות ומפריד הקנים אלך ואלך: **מקשה.** תרגומו נגיד, לשון המשכה שממשיך את האיברים מן העשת לכאן ולכאן בהקשת הקרנס, ולשון מקשה מכת קרנס, בטידי''ץ בלעז [עשוי בהכאה] כמו (דניאל ה ו) דא לדא נקשן: **תעשה המנורה.** מאליה, לפי שהיה משה מתקשה בה, אמר לו הקדוש ברוך הוא השלך את הככר לאור והיא נעשית מאליה, לכך לא נכתב תעשה: **ירכה.** הוא הרגל של מטה העשוי כמין תבה, ושלשה רגלים יוצאין המנה ולמטה: **וקנה.** הקנה האמצעי שלה העולה באמצע הירך זקוף כלפי מעלה, ועליו נר האמצעי עשוי כמין בזיך לצוק השמן לתוכו ולתת הפתילה: **גביעיה.** הן כמין כוסות שעושין מזכוכית ארכים וקצרים, וקורין להם מדרינ''ש בלעז [גביעים] , ואלו עשויין מזהב ובולטין ויוצאין מכל קנה וקנה כמנין שנתן בהם הכתוב, ולא היו בה אלא לנוי: **כפתריה.** כמין תפוחים עגולין סביב, בולטין סביבות הקנה האמצעי, כדרך שעושין למנורות שלפני השרים וקורין להם פומיל''ש בלעז [כפתורים] , ומנין שלהם כתוב בפרשה, כמה כפתורים בולטין ממנה, וכמה חלק בין כפתור לכפתור: **ופרחיה.** ציורין עשויין בה כמין פרחים: **ממנה יהיו.** הכל מקשה יוצא מתוך חתכת העשת, ולא יעשם לבדם וידביקם:
@32 **יצאים מצדיה.** לכאן ולכאן באלכסון, נמשכים ועולין עד כנגד גבהה של מנורה, שהוא קנה האמצעי, ויוצאין מתוך קנה האמצעי זה למעלה מזה, התחתון ארוך, ושל מעלה קצר המנו והעליון קצר המנו, לפי שהיה גובה ראשיהן שוה לגבהו של קנה האמצעי השביעי, שממנו יוצאים ששת הקנים:
@33 **משקדים.** כתרגומו, מצוירים היו כדרך שעושין לכלי כסף וזהב שקורין ניילי''ר : **ושלשה גבעים.** בולטין מכל קנה וקנה: **כפתר ופרח.** היה לכל קנה וקנה:
@34 **ובמנרה ארבעה גבעים.** בגופה של מנורה היו ארבעה גביעים אחד בולט בה למטה מן הקנים, והשלשה למעלה מן יציאת הקנים היוצאים מצדיה: **משקדים כפתריה ופרחיה.** זה אחד מחמשה מקראות שאין להם הכרע, שאין ידוע אם גביעים משקדים או משקדים כפתוריה ופרחיה:
@35 **וכפתר תחת שני הקנים.** מתוך הכפתור היו הקנים נמשכים משני צדיה אלך ואלך. כך שנינו במלאכת המשכן (פרק י) גבהה של מנורה שמונה עשר טפחים, הרגלים והפרח שלשה טפחים, הוא הפרח האמור בירך, שנאמר (במדבר ח ד) עד ירכה עד פרחה, וטפחיים חלק, וטפח שבו גביע מהארבעה גביעים, וכפתור ופרח משני כפתורים ושני פרחים האמורים במנורה עצמה, שנאמר משקדים כפתוריה ופרחיה, למדנו שהיו בקנה שני כפתורים ושני פרחים לבד מן השלשה כפתורים, שהקנים נמשכין מתוכן, שנאמר וכפתור תחת שני הקנים, וגו' וטפחים חלק, וטפח כפתור ושני קנים יוצאים ממנו אלך ואלך נמשכים ועולים כנגד גבהה של מנורה, וטפחיים חלק, וטפח כפתור ושני קנים יוצאים ממנו, וטפחיים חלק וטפח כפתור ושני קנים יוצאים ממנו ונמשכים ועולין כנגד גבהה של מנורה וטפחיים חלק, נשתיירו שם שלשה טפחים, שבהם שלשה גביעים וכפתור ופרח. נמצאו גביעים עשרים ושנים שמונה עשר לששה קנים, שלשה לכל אחד ואחד, וארבעה בגופה של מנורה, הרי עשרים ושנים, ואחד עשר כפתורים ששה בששת הקנים, ושלשה בגופה של מנורה, שהקנים יוצאים מהם, ושנים עוד במנורה, שנאמר משקדים כפתוריה, מעוט כפתורים שנים האחד למטה אצל הירך, והאחד בשלשת טפחים העליונים עם שלשת הגביעים, ותשעה פרחים היו לה ששה לששת הקנים, שנאמר (פסוק לג) בקנה האחד כפתור ופרח, ושלשה למנורה, שנאמר משקדים כפתוריה ופרחיה, ומיעוט פרחים שנים, ואחד האמור בפרשת בהעלותך (במדבר ח ד) עד ירכה עד פרחה. ואם תדקדק במשנה זו הכתובה למעלה, תמצאם כמנינם איש איש במקומו:
@37 **את נרתיה.** כמין בזכין שנותנין בתוכם השמן והפתילות: **והאיר על עבר פניה.** עשה ששת הנרות שבראשי הקנים, היוצאים מצדיה, מסבים כלפי האמצעי, כדי שיהיו הנרות כשתדליקם מאירים אל עבר פניה, מוסב אורם אל צד פני הקנה האמצעי, שהוא גוף המנורה:
@38 **ומלקחיה.** הם הצבתים העשויין לקח בהם הפתילה מתוך השמן לישבן ולמשכן בפי הנרות, ועל שם שלוקחים בהם קרויים מלקחים. וצבתהא שתרגם אנקלוס, לשון צבת, טינליי''א בלעז : **ומחתתיה.** הם כמין בזכין קטנים, שחותה בהן את האפר שבנר בבקר בבקר, כשהוא מטיב את הנרות מאפר הפתילות, שדלקו הלילה וכבו, ולשון מחתה פוישידויר''א בלעז [יעה] , כמו (ישעיה ל יד) לחתות אש מיקוד:
@39 **ככר זהב טהור.** שלא יהיה משקלה עם כל כליה אלא ככר, לא פחות ולא יותר, והככר של חול ששים מנה ושל קדש היה כפול, מאה עשרים מנה, והמנה הוא ליטרא ששוקלין בה כסף למשקל קולוני''א והם מאה זהובים, עשרים וחמשה סלעים והסלע ארבעה זהובים:
@40 **וראה ועשה.** ראה כאן בהר תבנית שאני מראה אותך, מגיד שנתקשה משה במעשה המנורה, עד שהראה לו הקדוש ברוך הוא מנורה של אש: **אשר אתה מראה.** כתרגומו דאת מתחזי בטורא, אלו היה נקוד מראה בפת''ח, היה פתרונו אתה מראה לאחרים, עכשו שנקוד חטף קמ''ץ, פתרונו דאת מתחזי, שאחרים מראים לך, שהנקוד מפריד בין עשה לנעשה:
@41 **ואת המשכן תעשה עשר יריעת.** להיות לו לגג ולמחצות מחוץ לקרשים שהיריעות תלויות מאחוריהן לכסותן: **שש משזר ותכלת וארגמן ותולעת שני.** הרי ארבע מינין יחד בכל חוט וחוט אחד של פשתים ושלשה של צמר, וכל חוט וחוט כפול ששה הרי ארבעה מינין, כשהן שזורין יחד, עשרים וארבע כפלים לחוט: **כרבים מעשה חשב.** כרובים היו מצוירין בהם באריגתן, ולא ברקימה שהוא מעשה מחט, אלא באריגה בשני כתלים, פרצוף אחד מכאן ופרצוף אחד מכאן, ארי מצד זה ונשר מצד זה, וכמו שאורגין חגורות של משי, שקורין בלעז פיישי''ש :
@43 **תהיין חברת.** תופרן במחט זו בצד זו, חמש לבד וחמש לבד: **אשה אל אחותה.** כך דרך המקרא לדבר בדבר שהוא לשון נקבה. ובדבר שהוא לשון זכר אומר איש אל אחיו, כמו שנאמר בכרובים (שמות כה כ) ופניהם איש אל אחיו:
@44 **ללאת.** לצול''ש בלעז [שרוכים] וכן תרגם אנקלוס ענובין, לשון עניבה: **מקצה בחברת.** באותה יריעה שבסוף החבור, קבוצת חמשת היריעות קרויה חוברת: **וכן תעשה בשפת היריעה הקיצונה במחברת השנית.** באותה יריעה שהיא קיצונה, לשון קצה, כלומר לסוף החוברת:
@45 **מקבילת הללאת אשה אל אחותה.** שמור שתעשה הלולאות במדה אחת מכונת הבדלתן זו מזו, וכמדתן ביריעה זו כן יהא בחברתה, כשתפרוש חוברת אצל חוברת, יהיו הלולאות של יריעה זו מכונות כנגד לולאות של זו. וזהו לשון מקבילות זו כנגד זו. תרגומו של נגד, קביל. היריעות ארכן עשרים ושמונה ורחבן ארבע, וכשחבר חמש יריעות יחד, נמצא רחבן עשרים, וכן החוברת השנית. והמשכן ארכו שלשים מן המזרח למערב, שנאמר עשרים קרש לפאת נגבה תימנה (פסוק יח) וכן לצפון, וכל קרש אמה וחצי האמה, הרי שלשים מן המזרח למערב. רוחב המשכן מן הצפון לדרום עשר אמות. שנאמר (כו כב. כג) ולירכתי המשכן ימה וגו' , ושני קרשים למקצעות, הרי עשר. ובמקומם אפרשם למקראות הללו. נותן היריעות ארכן לרחבו של משכן, עשר אמות אמצעיות לגג חלל רוחב המשכן, ואמה מכאן ואמה מכאן לעובי ראשי הקרשים שעבין אמה, נשתירו שש עשרה אמה, שמונה לצפון ושמונה לדרום מכסות קומת הקרשים שגבהן עשר, נמצאו שתי אמות התחתונות מגלות. רחבן של יריעות ארבעים אמה, כשהן מחברות עשרים אמה לחוברת, שלשים מהן לגג חלל המשכן לארכו ואמה כנגד עובי ראשי הקרשים שבמערב, ואמה לכסות עובי העמודים שבמזרח, שלא היו קרשים במזרח אלא ארבעה עמודים, שהמסך פרוש ותלוי בווין שבהן כמין וילון. נשתירו שמונה אמות התלויין על אחורי הקרשים שבמערב ושתי אמות התחתונות מגלות. זו מצאתי בברייתא דארבעים ותשע מדות. אבל במסכת שבת (צח ב) אין היריעות מכסות את עמודי המזרח, ותשע אמות תלויות אחורי המשכן, והכתוב מסייענו ונתת את הפרוכת תחת הקרסים, ואם כדברי הברייתא הזאת, נמצאת פרוכת משוכה מן הקרסים ולמערב אמה:
@46 **קרסי זהב.** פירמייל''ץ בלעז ומכניסין ראשן אחד בלולאות שבחוברת זו וראשן אחד בלולאות שבחוברת זו ומחברן בהן:
@47 **יריעות עזים.** מנוצה של עזים: **לאהל על המשכן.** לפרוש אותן על היריעות התחתונות:
@48 **שלשים באמה.** שכשנותן ארכן לרוחב המשכן, כמו שנתן את הראשונות, נמצאו אלו עודפות אמה מכאן ואמה מכאן לכסות אחת מהשתי אמות, שנשארו מגלות מן הקרשים, והאמה התחתונה של קרש, שאין היריעה מכסה אותו היא האמה התחובה בנקב האדן, שהאדנים גבהן אמה:
@49 **וכפלת את היריעה הששית.** העודפת באלו העליונות יותר מן התחתונות: **אל מול פני האהל.** חצי רחבה היה תלוי וכפול על המסך שבמזרח כנגד הפתח, דומה לכלה צנועה המכסה בצעיף על פניה:
@52 **וסרח העדף ביריעת האהל.** על יריעות המשכן. יריעות האהל הן העליונות של עזים שקרויים אהל, כמו שכתוב בהן (פסוק ז) לאהל על המשכן, וכל אהל האמור בהן אינו אלא לשון גג, שמאהילות ומסככות על התחתונות, והן היו עודפות על התחתונות חצי היריעה למערב, שהחצי של יריעה אחת עשרה היתרה, היה נכפל אל מול פני האהל, נשארו שתי אמות רוחב חציה עודף על רוחב התחתונות: **תסרח על אחרי המשכן.** לכסות שתי אמות שהיו מגלות בקרשים:
@53 **והאמה מזה והאמה מזה.** לצפון ולדרום: **בעדף בארך יריעת האהל.** שהן עודפות על אורך יריעות המשכן שתי אמות: **יהיה סרוח על צדי המשכן.** לצפון ולדרום, כמו שפירשתי למעלה. למדה תורה דרך ארץ שיהא אדם חס על היפה: **אחרי המשכן.** הוא צד מערבי, לפי שהפתח במזרח שהם פניו, וצפון ודרום קרויין צדדין לימין ולשמאל:
@54 **מכסה לאהל.** לאותו גג של יריעות עזים עשה עוד מכסה אחד של עורות אילם מאדמים, ועוד למעלה ממנו מכסה עורות תחשים, ואותן מכסאות לא היו מכסין אלא את הגג, ארכן שלשים ורחבן עשר, אלו דברי רבי נחמיה, ולדברי רבי יהודה מכסה אחד היה, חציו של עורות אילים מאדמים, וחציו של עורות תחשים:
@55 **ועשית את הקרשים.** היה לו לומר ועשית קרשים, כמה שנאמר בכל דבר ודבר, ומהו הקרשים, מאותן העומדין ומיחדין לכך. יעקב אבינו צפה ברוח הקדש ונטע ארזים במצרים, וכשמת צוה לבניו להעלותם עמהם כשיצאו ממצרים, אמר להם, שעתיד הקדוש ברוך הוא לצוות אתכם לעשות משכן במדבר מעצי שטים, ראו שיהיו מזמנים בידכם. הוא שיסד הבבלי בפיוט שלו טס מטע מזורזים קורות בתינו ארזים, שנזדרזו להיות מוכנים בידם מקדם לכן: **עצי שטים עומדים.** אישטנטיבי''ש בלעז שיהא אורך הקרשים זקוף למעלה בקירות המשכן, ולא תעשה הכתלים בקרשים שוכבים להיות רוחב הקרשים לגובה הכתלים קרש על קרש:
@56 **עשר אמות ארך הקרש.** למדנו שגבהו של משכן עשר אמות: **ואמה וחצי האמה רחב.** למדנו ארכו של משכן לעשרים קרשים, שהיו בצפון ובדרום מן המזרח למערב, שלשים אמה:
@57 **שתי ידות לקרש האחד.** היה חורץ את הקרש מלמטה, באמצעו בגובה אמה, מניח רביע רחבו מכאן ורביע רחבו מכאן, והן הן הידות, והחריץ חצי רוחב הקרש באמצע, ואותן הידות מכניס באדנים שהיו חלולים, והאדנים גבהן אמה ויושבים רצופים ארבעים זה אצל זה, וידות הקרש, הנכנסים בחלל האדנים, חרוצות משלשת צדיהן, רוחב החריץ כעובי שפת האדן, שיכסה הקרש את כל ראש האדן, שאם לא כן נמצא רוח בין קרש לקרש כעובי שפת שני האדנים שיפסיקו ביניהם, וזהו שנאמר (לקמן כד) והיו תאמים מלמטה, שיחרוץ את צדי הידות, כדי שיתחברו הקרשים זה אצל זה: **משלבת.** עשויות כמין שליבות סלם, מבדלות זו מזו ומשפין ראשיהם לכנס בתוך חלל האדן כשליבה, הנכנסת בנקב עמודי הסלם: **אשה אל אחתה.** מכונות זו כנגד זו, שיהיו חריציהם שוים, זו כמדת זו, כדי שלא יהיו שתי ידות זו משוכה לצד פנים וזו משוכה לצד חוץ בעובי הקרש שהוא אמה. ותרגום של ידות צירין, לפי שדומות לצירי הדלת הנכנסים בחורי המפתן:
@58 **לפאת נגבה תימנה.** אין פאה זו לשון מקצוע, אלא כל הרוח קרויה פאה, כתרגומו לרוח עבר דרומא:
@62 **ולירכתי.** לשון סוף, כתרגומו ולסיפי, ולפי שהפתח במזרח, קרוי המזרח פנים, והמערב אחורים, וזהו סוף, שהפנים הוא הראש: **תעשה ששה קרשים.** הרי תשע אמות רוחב:
@63 **ושני קרשים תעשה למקצעת.** אחד למקצוע צפונית מערבית ואחד למערבית דרומית, כל שמונה קרשים בסדר אחד הן, אלא שאלו השנים אינן בחלל המשכן, אלא חצי אמה מזו וחצי אמה מזו נראות בחלל להשלים רחבו לעשר, והאמה מזה והאמה מזה באות כנגד אמת עובי קרשי המשכן, הצפון והדרום, כדי שיהא המקצוע מבחוץ שוה:
@64 **ויהיו.** כל הקרשים תואמים זה לזה מלמטה שלא יפסיק עובי שפת שני האדנים ביניהם להרחיקם זו מזו. זהו שפרשתי (לעיל יז) שיהיו צירי הידות חרוצים מצדיהן, שיהא רוחב הקרש בולט לצדיו חוץ ליד הקרש לכסות את שפת האדן, וכן הקרש שאצלו, ונמצאו תואמים זה לזה. וקרש המקצוע שבסדר המערב חרוץ לרחבו בעביו כנגד חריץ של צד קרש הצפוני והדרומי, כדי שלא יפרידו האדנים ביניהם: **ויחדו יהיו תמים.** כמו תואמים: **על ראשו.** של קרש: **אל הטבעת האחת.** כל קרש וקרש היה חרוץ למעלה ברחבו שני חריצין בשני צדיו כדי עובי טבעת, ומכניסו בטבעת אחת, נמצא מתאים לקרש שאצלו. אבל אותן טבעות לא ידעתי אם קבועות הן אם מטולטלות. ובקרש שבמקצוע היה טבעת בעובי הקרש הדרומי והצפוני, וראש קרש המקצוע שבסדר מערב נכנס לתוכו, נמצאו שני הכתלים מחברים: **כן יהיה לשניהם.** לשני הקרשים שבמקצוע, לקרש שבסוף צפון ולקרש המערבי וכן לשני המקצועות:
@65 **והיו שמנה קרשים.** הם האמורים למעלה (פסוקים כב. כג) תעשה ששה קרשים ושני קרשים תעשה למקצעות, נמצאו שמנה קרשים בסדר מערבי. כך שנויה במשנת מעשה סדר הקרשים במלאכת המשכן (פרק א) היה עושה את האדנים חלולים, וחורץ את הקרש מלמטה רביע מכאן ורביע מכאן, והחריץ חציו באמצע, ועשה לו שתי ידות כמין שני חמוקין ולי נראה שהגרסא כמין שני חוקין, כמין שתי שליבות סלם המובדלות זו מזו ומשפות להכנס בחלל האדן כשליבה, הנכנסת בנקב עמוד הסלם, והוא לשון משלבות, עשויות כמין שליבה, ומכניסן לתוך שני אדנים, שנאמר (פסוק יט) שני אדנים ושני אדנים, וחורץ את הקרש מלמעלה אצבע מכאן ואצבע מכאן ונותן לתוך טבעת אחת של זהב כדי שלא יהיו נפרדים זה מזה, שנאמר (פסוק כד) והיו תואמים מלמטה וגו' . כך היא המשנה, והפרוש שלה הצעתי למעלה בסדר המקראות:
@66 **בריחם.** כתרגומו עברין ובלעז אישבר''ש : **חמשה לקרשי צלע המשכן.** אלו חמשה שלשה הן, אלא שהבריח העליון והתחתון עשוי משתי חתכות, זה מבריח עד חצי הכתל וזה מבריח עד חצי הכתל, זה נכנס בטבעת מצד זה וזה נכנס בטבעת מצד זה, עד שמגיעין זה לזה, נמצאו שעליון ותחתון שנים שהן ארבע, אבל האמצעי ארכו כנגד כל הכתל ומבריח מקצה הכתל ועד קצהו, שנאמר (פסוק כח) והבריח התיכון וגו' מבריח מן הקצה אל הקצה, שהעליונים והתחתונים היו להן טבעות בקרשים להכנס לתוכן שתי טבעות לכל קרש, משלשים בתוך עשר אמות של גובה הקרש, חלק אחד מן הטבעת העליונה ולמעלה וחלק אחד מן התחתונה ולמטה, וכל חלק הוא רביע אורך הקרש, ושני חלקים בין טבעת לטבעת, כדי שיהיו כל הטבעות מכונות זו כנגד זו. אבל לבריח התיכון אין טבעות, אלא הקרשים נקובין בעביין והוא נכנס בהם דרך הנקבים שהם מכונין זה מול זה, וזהו שנאמר בתוך הקרשים. הבריחים העליונים והתחתונים שבצפון ושבדרום אורך כל אחת חמשה עשר אמה, והתיכון ארכו שלשים אמה, וזהו מן הקצה אל הקצה, מן המזרח ועד המערב, וחמשה בריחים שבמערב אורך העליונים והתחתונים שש אמות והתיכון ארכו שתים עשרה כנגד רוחב שמונה קרשים, כך היא מפרשת במלאכת המשכן (פרק א) :
@69 **בתים לבריחם.** הטבעות, שתעשה בהן, יהיו בתים להכניס בהן הבריחים: **וצפית את הבריחם זהב.** לא שהיה הזהב מדבק על הבריחים, שאין עליהם שום צפוי, אלא בקרש היה קובע כמין שני פיפיות של זהב כמין שני סדקי קנה חלול, וקובען אצל הטבעות לכאן ולכאן ארכן ממלא את רוחב הקרש מן הטבעת לכאן וממנה לכאן והבריח נכנס לתוכו וממנו לטבעת ומן הטבעת לפה השני, נמצאו הבריחים מצפין זהב, כשהן תחובין בקרשים, והבריחים הללו מבחוץ היו בולטות והטבעות והפיפיות לא היו נראות בתוך המשכן אלא כל הכתל חלק מבפנים:
@70 **והקמת את המשכן.** לאחר שיגמר הקימהו: **הראית בהר.** קדם לכן, שאני עתיד ללמדך ולהראותך סדר הקמתו:
@71 **פרכת.** לשון מחצה הוא, ובלשון חכמים פרגוד, דבר המבדיל בין המלך ובין העם: **תכלת וארגמן.** כל מין ומין היה כפול, בכל חוט וחוט ששה חוטין: **מעשה חשב.** כבר פרשתי שזו היא אריגה שלשני קירות, והציורין שמשני עבריה אינן דומין זה לזה: **כרובים.** ציורין של בריות יעשה בה:
@72 **ארבעה עמודי שטים.** תקועים בתוך ארבעה אדנים ואונקליות קבועין בהן עקומים למעלה להושיב עליהן כלונס שראש הפרוכת כרוך בה, והאונקליות הן הווין, שהרי כמין ווין הן עשוים, והפרכת ארכה עשר אמות לרחבו של משכן, ורחבה עשר אמות כגבהן של קרשים, פרוסה בשלישית של משכן, שיהא המנה ולפנים עשר אמות, והמנה ולחוץ עשרים אמה, נמצא בית קדשי הקדשים עשר על עשר, שנאמר ונתת את הפרכת תחת הקרסים, המחברים את שתי חוברות של יריעות המשכן, ורוחב החוברת עשרים אמה, וכשפרשה על גג המשכן מן הפתח למערב, כלתה בשני שלישי המשכן, והחוברת השניה כסתה שלישו של משכן, והמותר תלוי לאחוריו לכסות את הקרשים:
@75 **ושמת את השלחן.** שלחן בצפון, משוך מן הכתל הצפוני שתי אמות ומחצה. ומנורה בדרום משוכה מן הכתל הדרומי שתי אמות ומחצה. ומזבח הזהב נתון כנגד אויר שבין שלחן למנורה, משוך קמעא כלפי המזרח, וכלם נתונים מן חצי המשכן ולפנים. כיצד, אורך המשכן מן הפתח לפרכת עשרים אמה, המזבח והשלחן והמנורה משוכים מן הפתח לצד מערב עשר אמות:
@76 **ועשית מסך.** וילון שהוא מסך כנגד הפתח, כמו (איוב א י) שכת בעדו, לשון מגן: **מעשה רקם.** הצורות עשויות בו מעשה מחט, כפרצוף של עבר זה כך פרצוף של עבר זה: **רקם.** שם האמן, ולא שם האמנות, ותרגומו עובד ציר. מדת המסך כמדת הפרוכת, עשר אמות על עשר אמות:
@78 **ועשית את המזבח** וגו' **ושלש אמות קומתו.** דברים ככתבן, דברי רבי יהודה. רבי יוסי אומר נאמר כאן רבוע, ונאמר בפנימי רבוע, מה להלן גבהו פי שנים כארכו, אף כאן גבהו פי שנים כארכו. ומה אני מקים ושלש אמות קומתו, משפת סובב ולמעלה:
@79 **ממנו תהיין קרנתיו.** שלא יעשם לבדם ויחברם בו: **וצפית אותו נחשת.** לכפר על עזות מצח, שנאמר (ישעיה מח ד) ומצחך נחושה:
@80 **סירתיו.** כמין יורות: **לדשנו.** להסיר דשנו לתוכם, והוא שתרגם אנקלוס למספי קטמיה, לספות הדשן לתוכם, כי יש מלות בלשון עברית מלה אחת מתחלפת בפתרון לשמש בנין וסתירה, כמו (תהלים פ י) ותשרש שרשיה, (איוב ה ג) אויל משריש. וחלופו (שם לא יב) ובכל תבואתי תשרש. וכמוהו (ישע' יז ו) בסעיפיה פריה, וחלופו (שם י לג) מסעף פארה, מפשח סעיפיה, וכמוהו (ירמיה נ יז) וזה האחרון עצמו, שבר עצמיו, וכמוהו (מל''א כא יג) ויסקלהו באבנים, וחלופו (ישע' סב י) סקלו מאבן, הסירו אבניה, וכן (שם ה ב) . ויעזקהו ויסקלהו, אף כאן לדשנו להסיר דשנו ובלעז אישצינדרי''ר : **ויעיו.** כתרגומו, מגרפות שנוטל בהם הדשן, והן כמין כסוי הקדרה של מתכת דק ולו בית יד, ובלעז וידי''ל : **ומזרקתיו.** לקבל בהם דם הזבחים: **ומזלגתיו.** כמין אנקליות כפופים, ומכה בהם בבשר ונתחבים בו ומהפך בהן על גחלי המערכה שיהא ממהר שרפתן ובלעז קרוצינ''ש [אנקולים] ובלשון חכמים צנוריות: **ומחתתיו.** בית קבול יש להם לטול בהן גחלים מן המזבח לשאתם על מזבח הפנימי לקטרת, ועל שם חתייתן קרויים מחתות, כמו (ישעיה ל יד) לחתת אש מיקוד, לשון שאיבת אש ממקומה, וכן (משלי ו כז) היחתה איש אש בחיקו: **לכל כליו.** כמו כל כליו:
@81 **מכבר.** לשון כברה, שקורין קריבל''א כמין לבוש עשוי לו למזבח, עשוי חורין חורין כמין רשת. ומקרא זה מסורס וכה פתרונו ועשית לו מכבר נחשת מעשה רשת:
@82 **כרכב המזבח.** סובב, כל דבר המקיף סביב בעגול קרוי כרכוב, כמו ששנינו בהכל שוחטין (חולין כה א) אלו הן גלמי כלי עץ, כל שעתיד לשוף ולכרכב, והוא כמו שעושין חריצין עגולין בקרשי דפני התבות וספסלי העץ, אף למזבח עשה חריץ סביבו והיה רחבו אמה בדפנו לנוי והוא לסוף שש אמות של גבהו, כדברי האומר גבהו פי שנים כארכו, הא מה אני מקים ושלש אמות קומתו, משפת סובב ולמעלה. אבל סובב להלוך הכהנים לא היה למזבח הנחשת אלא על ראשו לפנים מקרנותיו, וכן שנינו בזבחים (סב ב) איזהו כרכוב, בין קרן לקרן ולפנים מהן אמה של הלוך רגלי הכהנים, ושתי אמות הללו קרויים כרכוב. ודקדקנו שם והכתיב תחת כרכוב המזבח מלמטה, למדנו שהכרכוב בדפנו הוא ולבוש המכבר תחתיו. ותירץ המתרץ תרי הוו, חד לנוי וחד לכהנים דלא ישתרגו. זה שבדופן לנוי היה ומתחתיו הלבישו המכבר והגיע רחבו עד חצי המזבח. נמצא שהמכבר רחב אמה, והוא היה סימן לחצי גבהו להבדיל בין דמים העליונים לדמים התחתונים. וכנגדו עשו למזבח בית עולמים חגורת חוט הסקרא באמצעו. וכבש שהיו עולין בו אף על פי שלא פרשו בענין זה, כבר שמענו בפרשת (לעיל כ כ) מזבח אדמה תעשה לי (לעיל כ כב) ולא תעלה במעלות, לא תעשה לי מעלות בכבש שלו אלא כבש חלק למדנו שהיה לו כבש, כך שנינו במכילתא. ומזבח אדמה הוא מזבח הנחשת שהיו ממלאין חללו אדמה במקום חניתן. והכבש היה בדרום המזבח מבדל מן המזבח מלא חוט השערה, ורגליו מגיעין עד אמה סמוך לקלעי החצר שבדרום, כדברי האומר עשר אמות קומתו. ולדברי האומר דברים ככתבן שלש אמות קומתו לא היה אורך הכבש אלא עשר אמות, כך מצאתי במשנת מ''ט מדות, וזה שהיה מבדל מן המזבח מלא החוט, במסכת זבחים (סב ב) למדוה מן המקרא:
@84 **בטבעת.** בארבע טבעות שנעשו למכבר:
@85 **נבוב לחת.** כתרגומו חליל לוחין. לוחות עצי שטים מכל צד והחלל באמצע, ולא יהא כלו עץ אחד שיהא עביו חמש אמות על חמש אמות כמין סדן:
@86 **קלעים.** עשויין כמין קלעי ספינה נקבים נקבים מעשה קליעה ולא מעשה אורג ותרגומו סרדין כתרגומו של מכבר המתורגם סרדא לפי שהן מנקבין ככברה: **לפאה האחת.** כל הרוח קרוי פאה:
@87 **ועמדיו עשרים.** חמש אמות בין עמוד לעמוד: **ואדניהם.** של עמודים נחשת, האדנים יושבים על הארץ והעמודים תקועים לתוכן היה עושה כמין קונדסין שקורין פל''ש בלעז ארכן ששה טפחים ורחבן שלשה וטבעת נחשת קבועה בו באמצעו, וכורך שפת הקלע סביבו במיתרים כנגד כל עמוד ועמוד, ותולה הקונדס דרך טבעתו באונקליות שבעמוד העשוי כמין ו''ו, ראשו זקוף למעלה וראשו אחד תקוע בעמוד, כאותן שעושין להציב דלתות שקורין גונזי''ש בלעז ורחב הקלע תלוי מלמטה, והיא קומת מחיצות החצר: **ווי העמודים.** הם האונקליות: **וחשקיהם.** מקפין היו העמודים בחוטי כסף סביב. ואיני יודע אם על פני כלן, אם בראשם, אם באמצעם. אך יודע אני שחשוק לשון חגורה, שכן מצינו בפילגש בגבעה (שופטים יט יז) ועמו צמד חמורים חבושים, תרגומו חשוקים:
@90 **לפאת קדמה מזרחה.** פני המזרח קרוי קדם, לשון פנים. אחור לשון אחורים, לפיכך המזרח קרוי קדם שהוא פנים, ומערב קרוי אחור, כמו דתרגם אנקלוס (דברים יא כד) הים האחרון ימא מערבאה: **חמשים אמה.** אותן חמשים אמה לא היו סתומים כלם בקלעים, לפי ששם הפתח, אלא חמש עשרה אמה קלעים לכתף הפתח מכאן, וכן לכתף השנית, נשאר רחב חלל הפתח בינתים עשרים אמה וזה שנאמר (פסוק טז) ולשער החצר מסך עשרים אמה, וילון למסך כנגד הפתח עשרים אמה ארך כרחב הפתח:
@91 **עמדיהם שלשה.** חמש אמות בין עמוד לעמוד, בין עמוד שבראש הדרום העומד במקצוע דרומית מזרחית עד עמוד שהוא מן השלשה שבמזרח חמש אמות וממנו לשני חמש אמות, ומן השני לשלישי חמש אמות, וכן לכתף השנית, וארבעה עמודים למסך, הרי עשרה עמודים למזרח כנגד עשרה למערב:
@94 **כל עמודי החצר סביב** וגו' **.** לפי שלא פרש ווין וחשוקים ואדני נחשת אלא לצפון ולדרום, אבל למזרח ולמערב לא נאמר ווין וחשוקים ואדני נחשת, לכך בא ולמד כאן:
@95 **ארך החצר.** הצפון והדרום שמן המזרח למערב מאה באמה: **ורחב חמשים בחמשים.** חצר שבמזרח היתה מרבעת חמשים על חמשים, שהמשכן ארכו שלשים ורחבו עשר, העמיד מזרח פתחו בשפת חמשים החיצונים של אורך החצר נמצא כלו בחמשים הפנימיים, וכלה ארכו לסוף שלשים נמצאו עשרים אמה רוח לאחוריו בין הקלעים שבמערב ליריעות של אחורי המשכן, ורוחב המשכן עשר אמות באמצע רחב החצר, נמצאו לו עשרים אמה רוח לצפון ולדרום מן קלעי החצר ליריעות המשכן, וכן למערב, וחמשים על חמשים חצר לפניו: **וקמה חמש אמות.** גובה מחצות החצר, והוא רוחב הקלעים: **ואדניהם נחשת.** להביא אדני המסך, שלא תאמר לא נאמרו אדני נחשת אלא לעמודי הקלעים, אבל אדני המסך של מין אחר היו. כך נראה בעיני, שלכך חזר ושנאן:
@96 **לכל כלי המשכן.** שהיו צריכין להקמתו ולהורדתו, כגון מקבות לתקוע יתדות ועמודים: **יתדות.** כמין נגרי נחשת עשויין ליריעות האהל ולקלעי החצר, קשורים במיתרים סביב סביב בשפוליהן, כדי שלא תהא הרוח מגביהתן. ואיני יודע, אם תחובין בארץ או קשורין ותלויין וכבדן מכביד שפולי היריעות, שלא ינועו ברוח. ואומר אני ששמן מוכיח עליהם שהם תקועין בארץ, לכך נקראו יתדות, ומקרא זה מסיעני (ישעיה לג כ) אהל בל יצען בל יסע יתדותיו לנצח:

@2 **ויקחו לי תרומה.** הרצון בו שיפרישו אותה לשמי וידמה שזאת התרומה הוא זולת התרומה שרמז אליה באמרו מאת כל איש אשר ידבנו לבו תקחו את תרומתי. וזה שכבר נזכר בפרשת אלה פקודי כי כסף העשוי למלאכת המקדש הפרישוהו ישראל כשנתן כל אחד מהם מבן עשרים שנה ומעלה מחצית השקל והנה זאת התרומה היתה מוגבלת לא היתה נוספת מצד הנדבה ולא נגרעת מצד העדר הנדבה ועליה אמר ויקחו לי תרומה על צד הצואה וכבר היתה שם תרומה אחרת שהיתה לפי הנדבה והיא תנופת הזהב ושאר הענינים הנוהגים מנהגו שהיו צריכים למלאכת הקדש כמו שנזכר בפרשת ויקהל כל נדיב לבו הביאו חח ונשם וגו' כל איש אשר נמצא אתו תכלת וארגמן וגו' והנשיאים הביאו את אבני השוהם ואבני המלואים והנה כלל שאר מיני אלו התרומות במה שאמר וזאת התרומה אשר תקחו מאתם ולזה זכר שם הכסף עם הזהב והנחשת והנה הכסף בא בקע לגלגולת והזהב והנחשת היא בא נדבה או אולי היה שם כסף גם כן שיהיה בא נדבה ולא נכלל במלאכת המקדש הנזכרת בפרשת ואלה פקודי ואולם עשו ממנו כלי שרת:
@4 **תכלת.** הוא צמר צבוע בצבע שעינו דומה לעין הים או לעין השמים:
@4 **והארגמן.** הוא צמר צבוע אדום:
@4 **ותולעת שני.** הוא צמר צבוע בצבע אדום גרנ"א בלעז ואין אדמימותו במדרגת אודם הארגמן:
@4 **ושש.** הוא מן הפשתים הנבחרי' וכשיהיה חוטו כפול לששה הרי נקרא שש או שש משזר וכשלא היה חוטו כפול ששה נקרא בד וזה כלו לפי מה שיורה עליו הגדר כי בד יורה על היחידיות ושש על הששה ושם הענין בעצמו הוא פשתים או בוץ:
@4 **ועזים.** הוא הצמר הרך ההוה בעזים סביב שרשי השערות הקשות והוא כתכלית הרכו':
@5 **ועורות אלים מאדמים.** הם עורות אלים צבועים בצבע אדום גוד"א מנס"י בלעז:
@5 **ועורות תחשים.** אחשוב כי הם תישים גדולים ועורותיהם יותר חזקים ויתר קשים ויותר נבחרי' מהאלו' על כן כתוב ואנעלך תחש שהוא הנבחר שבעורות לעשו' מנעלים ורז"ל אמרו שהוא מין חיה לעורה גונין הרבה:
@5 **ועצי שטים.** הוא ממין הארזים יתכן שכרתו שיש אותם באחד מהם מהמקומות אשר עבדו בהם לעשות מהם שולחנות ומה שידמה להם והתנדבו אותם מי שנמצאו בידיהם כמו שמפורש בפרשת ויקהל:
@6 **שמן למאור.** הוא שמן זית זך כתית והיה נבחר מאד ולזה לא נמצא כי אם ביד הנשיאים כמו שמפורש בפרשת ויקהל:
@6 **שמן המשחה.** הוא שמן מרוקח עם הבשמים יבא זכרונם במה שיבא ובו היו מושחים הדברים שרצונם לקדשם כמו המשכן וכלו והכהנים על האופן שהתבאר והנה בקטרת הסמים היו נכנסים בשמים יבא זכרונם במה שיבא:
@7 **אבני שוהם.** הם אבנים טובות היו בכתפות האיפוד ובחושן ג"כ היתה נכנסת עם שאר אבני' טובות יבא זכרונם במה שיבא והם אבני המלואים שזכר בזה המקום וקראם אבני המלואים כי היו עושים להם גומא בחושן ומשימים אותם האבנים שם למלאת הגומא ההוא:
@8 **ועשו לי מקדש.** הוא מצות עשה וזאת העשייה יחוייב בשתהיה לשמו יתע' שנאמר ועשו לי ויחוייב היותה ביום כמו שהתבאר בשרשים הכוללים והנה עשיית זה המקדש הוא שנעשה אוהל או בית ויהיו שם כלים מוגבלים בתואר הנזכר במה שיבא והנה נקרא זה המקום מקדש להיותו קדוש כי הוא מוכן לעבוד בו השם יתע' והוא גם כן מעיד על מציאותו כמו שנבאר במה שיבא בג"ה ולזה אמר ושכנתי בתוכם ר"ל כי זה המקד' יהיה סבה שתהיה שכינתי בתוכם וראוי שיהיה המקדש נעשית מן כלל ישראל או שיתנדבו אותם הענינים יחידים לצבור ולש' יתע' שנאמר ועשו לי מקדש וראוי היה להיות כן לפי שעיונו משותף לכל ישראל ולזה תמצא שעבודת אהל מועד היתה באה משל צבור שוה בשוה כמו שנבאר בפרשת תשא. וראוי שלא יעלם שזאת המצוה אינה באי זה מקום הזדמן מהמקומות אבל במקום אשר יבחר יי' כמו שנזכר ועליו אמר בפרשת ראה כי לא באתם עד עתה וגו' ועברתם את הירדן וישבתם בארץ והיה המקום אשר יבחר יי' והו' המקום אשר כשנגלה ענינו לא הותר להיות המקדש אלא בו וזה המקום הוא בהר המוריה ועליו אמר דוד בספר דברי הימים זהו בית יי' אלהים וזה מזבח לעולה ועליו אמר בספר תלים זאת מנוחתי עדי עד וכזה המקום היה בית המקדש ולא הותר להיות המשכן אלא בו אחר הגלותו. ואולם המשכן שהי' במדבר היה לפי שעה לחנך ישראל לעבודת השם יתע' באופן שיהיו לו לעם וינחילם את הארץ ולא סרו שלא היה להם משכן או בית עד שנגלה להם מקום בית עולמים. ולזה לא תנהג זאת המצוה אלא במקום ההוא שיהיה בו בית המקדש בהר המוריה:
@9 **כל אשר אני מראה אותך את תבנית המשכן ואת תבנית כל כליו.** יעשו לי עתה מקדש במדבר:
@9 **וכן תעשו.** לדורות ר"ל שתעשו צורת המשכן וכליו על זה האופן ואולם שיעור המשכן לא יחוייב שלא יוסיף על זה השיעור וזה דבר מבואר מהבנין שעשה שלמה על פי נביא כמו שהורוהו דוד אביו באמרו הכל בכתב מיד יי' עלי השכיל. ומזה המקום יתבאר ששעורי הבית ההוא יחוייב שיהיו נודעים על פי נביא כמו שנודע אלו השעורים על ידי משה. וראוי שגם כן יהיה שם מלך וכהן גדול וסנהדרי גדול' כמו שהיה במשכן הנעשה על יד משה כי הוא היה מלך ונביא והיה שם אהרן שהיה כהן גדול ושבעים איש מזקני ישר' שהיו סנהדרין וכן הענין במקדש שעשה שלמה וראוי היה להיות כן כי אלו הענינים הגדולים המשותפים לישראל בכללם ראוי שיעשו ע"י מי שיכללום בהנהגותיהם בכל אופני ההנהגה ולה אמרו שאין מוסיפין על העיר ועל העזרו' אלא בכל אלו התנאים ולמדו זה ממה שאמ בזה המקום וכן תעשו. וכן לא יחוייב שיהיו כלי המקדש מהמתכות הנזכרים בכאן כי לא צוה אלא שיעשו אותם בזה התבנית שזכר לא מהמתכות שזכר ואמנם יהיה זה למצוה מן המובחר ואין ספק שמצות עשיית המשכן או המקדש נוהגת לדורות כי כבר נזכרו בתורה מצות רבות נוהגות לדורות לא ישלמו אלא בה והנה התועלת בזאת המצוה כבר זכרנוהו ויתבאר ביאור שלם במה שיבא:
@10 **הנה** הארון לא היו לו רגלים לפי הנראה מהשפט וקומתו היתה אמה וחצי כשנמדוד מבחוץ וכן היה גובה השלחן עם רגליו והנה עוביו לא נודע לנו מפשטי הכתוב ועכ"פ היה עוביו נאות אל שיתקיים זמן אורך נפלא וכבר יתבאר לך שזאת המדה היתה מבחוץ שאם נמדוד הרוחב והאורך מבפני' היה הכפרת נופל בתוך הארון כי היה ארכו כארך הארון ורחבו כרחבו וצפית אותו זהב טהור אין ספר שזה הצפוי לא היה באופן צפוי הזהב לכסף שהיא קליפה דקה מאד כי לא ידבק הזהב בעץ בזה האופן ולא יהיה לו קיום. ולזה הוא מבואר ששלשה ארונות נעשו אחד מעץ ואחד מזהב נכנס לתוכו בצמצום ואחד מזהב מקיף בו בצמצום. וכבר היו זה באופן שכל ארון העץ היה מצופה זהב ועובי ארונות הזהב לא נודע ועכ"פ היה להם עובי מרגש כדי שישלם להם הקיום ולא יתכן שיהיה עובי ארונות הזהב טפח כמו שאמרו ז"ל כי לא יתכן שישלם אחד מאלו הארונות בזה העובי מכל הזהב הנזכר באלה פקודי העשוי למלאכה וזה יתבאר למי שעיין בהנדסה עיון מעט ואולם אמרו זה ז"ל להודות על שכבר היה לאלו הארונות עובי מורגש:
@11 **ועשית עליו זר זהב סביב.** הוא סבוב מזהב מקיף על עליוני הארון מבחוץ כדי שיכנס בו הכפרת ויחזיק בו:
@12 **ויצקת לו ארבע טבעות זהב.** רצה שיעשו אלו הטבעות על צד ההתכה כדי שיהיה התדבקותם מעצמותם ויהיה יותר חזקים:
@12 **על ארבע פעמותיו.** ר"ל זויותיו והוא מענין פעם כי הפעם הוא השניות והעדר התדבקות וכן הענין בזויות כי בהם יחלקו השטחים המקיפים בדבר קצתם מקצת והנה היו שתי טבעות מהם על הצלע האחד מצלעות הרוחב ושתי טבעות על צלעו השנית ובהם היו נכנסים הבדים המצופים לשאת הארון בהם והיה זה כן מפני שהעדות הנתן בארון היה דבר שלם בעצמותו והדבר השלם הוא מה שלא יחסר בו דר רצה השם יתע' שימצא בו השלמות בארון בכל הפנים עד שלא יחסר בו דבר אבל ימצא תמיד מוכן אל השלמות מבלי שיצטרך להביא בו דבר מחוץ:
@18 **כרובים.** הם כצורות בן אדם צעיר הימים ונקראו צעירי הימים רובים מפני גדול הנפלא הנמצא בהם ותהיה הכ"ף בזה השם כמו כ"ף הדמיון והשתמשו בו כאלו היתה שרש:
@18 **מקשה.** ר"ל שיעשה זה הכפרת כשיקיש בקורנס על עשת הזהב באופן שיעשה הכרובים בזאת ההקשה משני קצות הכפרת כדי שיהיו הכרובים והכפרת מחתיכה אחת במספר והנה היו הכרובים פורשי כנפים למעלה כאלו ירצו לעוף להגביה עצמו למעלה ובזה האופן היו סוככים בכנפיהם על הכפרת כאלו היו כנפיהם סוכה עליה והכרובים היו הופכים פניהם איש אל אחיו ועם היות פניהם איש אל אחיו היו פניהם נוטות למטה אל אמצע הכפרת כאלו הם מביטים אל מה שלמטה מהם:
@21 **ונתת את הכפרת על הארון מלמעלה.** במדרגת כסוי ואל הארון תתן קודם זה את העדות אשר אתן אליך והם שתי לוחות אבנים כמו שנזכר בספר מלכים אין בארון רק שני לוחות האבנים אשר הניח שם משה בחורב והנה זכר בזה המקום שנית נתינה בעדות בארון להורות שאין ראוי שיושם הכפורת על הארון כי אם אחר שינתן בו העדות כדי שלא ימצא בו החסרון בדרך שיצטרך להסיר הכפרת להניח שם העדות ועוד העיר בזה כי היות הכפרת בזאת הצורה הוא מכוון מפני העדות הנתן בתוך הארון וכבר יתבאר זה מדברינו בגזרת הצור כאשר נבא הסבה אשר הביאה להעשות זה בזה האופן:
@22 **ונועדתי לך שם.** ר"ל ששם יראה ענן יי' בדברי עמך כאלו אני מדבר עמך מהמקום ההוא כמו שהיה הענין בהר סיני שנראה שם כבוד יי' בהגיע הנבואה למשה ודברי אתך מעל הכפרת מבין שני הכרובי' אשר על ארון העדות וגו' כדי שיתפרסם להם כי משם אני מגיע אליך הנבואה כי זה ממה שיישירם להשיג מה שכוון בעשיית הכפרת והכרובים בזה התואר על ארון העדות:
@23 **ועשית שלחן** עצי שטים שנים עשר טפחים ארכו וששה טפחים רוחבו ואמה וחצי היתה קומתו עם רגליו והיה מצופה זהב טהור על האופן שזכרנו בצפוי הארון ועשית לו זר זהב ר"ל שיקיף בו סבוב הזהב גבוה מעט כמו שנהוג בשלחנות היפי' לעשותם בזה התואר כדי שיחזיקו בדברי' אשר ישימו עליו ולא יפלו ממנו:
@25 **ועשית לו מסגרת טופח סביב.** הנה זה המסגרת היה מה שקבועים בו רגלי השלחן לארבע הפאות והיה עביו טפח כדי שישלם בו החוזק והקיום ואחשוב שרחבו היה ג"כ טפח ועל המסגר היו מניחים השלחן כדי שלא יהיו קבועים רגלי השלחן והיה זר זהב סביב המסגרת כדי שיכנס השלחן בתוכו ויחזיק בו באופן שיהיה מקי בכפרת זר הזהב אשר בארון ולה אמר לעומת המסגרת תהיין הטבעות שאם היו הטבעות בשלחן הנה בשאתם השלחן ישארו בארץ רגלי השלחן ומסגרתו ואמנם כשהיו לעומת המסגרת היו נושאים המסגרת והשלחן אשר בו יחד קערותיו הם הדפוסים שהיו אופין בהם לחם הפנים ומניחים אותן בהן עד שיערכוהו על השלחן:
@29 **וכפותיו.** הם הכפות שמניחין בהן הלבונה אצל מערכת לכם הפנים כמו שיתבאר במה שיבא:
@29 **וקשותיו.** הם סעיפי ילן מפורצלין פצולין לסמוך בהם המנקיו' אשר עליהם יונח לחם הפנים והיו שם ארבעה קשות היו קבועים בקרקע כנגד בדי השלחן:
@29 **והמנקיות.** הן כמו חצאי קנים חלולים וכ"ח מנקיות היו שם י"ד לכל מערכת וזה שכבר היה מניח הלחם הראשון על השלחן ואחר מניח שלש מנקיות על הלחם ההוא והם נסמכות בקשות ועליה היה מניח הלחם השני וכן בזה האופן עד הלחם החמישי ובין לחם החמישי והשישי לא היה משים כי אם שתי מנקיות כי אין עליו זולת הלחם הששי לחם הפנים ראוי שתדע שכבר היו על השלחן י"ב חלות וכל אחת היתה עשויה משני עשרונים סלת כמו שיתבאר בסוף פרשת אמור אל הכהנים:
@30 ותאר אלו החלות היו באופן שהיתה כל אחד מהם **לחם הפנים** ר"ל לחם שיש לו פנים רבים וכבר התבאר באחד עשר ממנחות תואר עשייתם והוא שהיו עושין חלה ארכה עשרה טפחים ורחבה ה' טפחים וקרנותיה שבע אצבעות וכופל מן האורך טפחים מכאן וטפחים מכאן ואותן הטפחים עומדים בגובה כמו דפנות וענין קרנותיה הוא לפי הנראה לי כי לא היתה החלה בעלת ארבעה צלעות בשלמות אבל היתה בעלת שמנה צלעות ארבע צלעות לצד הזויות באלכסון והם אשר קראום קרנות ואורך כל קרן מהם היה שבע אצבעות ובזה האופן ישלם לזה הלחם שיהיו לו פנים רבי' בכל אחד משטחיו המקיפים בו כי כל אחד מששה השטחים המקיפים בכל גוף שיהיה בזה התואר נחלק לשלשה שטחים עד שכבר יקיפו בו יח' שטחין שבע שטחים בכל אחד מדפניו ארבע בתושבת החלה ואולם עובי אלו החלות לא הוגבל כי כבר יתחלף לפי קושי הבצק ורכותו ולפי דעתי היה עוביו פחות מאצבע וזה יתבאר משעור עשרון שהוא עשירית שלש סאין ואמה על אמה ברום שלש אמות היה מחזיק ארבעים סאה. ולזה יהיה שעור העשרון אמה על אמה ברום חצי אצבע וחמישית חומש אצבע שהם כמו שלש מאות אצבעות ורביע אצבע בקרוב ובהיו' הענין כן הנה החלה הנעשת משני עשרוני' מעשרה טפחי' אורך וחמשה טפחים רחב לא יהיה כי אם שש שמיניות אצבע בקרוב כשהונח שיעור הבצק כשיעור הסולת אשר ממנו נעשה והו' מבואר שהבצק כשיהיה מצה לא יהיה נוסף כמותו על כמות הקמח ואם היה שיהיה נוסף הנה הוא מעט אבל יראה בחוש שכמות הבצק הזה הוא פחות מכמות הקמח ולזה לא יתכן שיהיה עובי אלו החלות כי אם פחות מאצבע ולזאת הסבה תמהנו על הרב רבינו משה במה שפירש וקרנותיו שבע שעובי החלה היה שבע אצבעות ועוד שכבר התבאר שם שיעור שתי הלחם שהיו באים בעצרת שהם באים חמץ שהיה כל אחד מהם עשרון והנה היה ארכו שבע טפחים ורחבו ארבעה טפחים וקרנותיו דאצבעות והוא מבואר שהבצק שיהיה חמץ הוא יותר רב הכמות ממה שהיה בהיותו מצה ואם היה הרצון בקרנותיו עביו הנה יהיה שיעור החלה שהיא מצה הבאה משני עשרונים יותר משלשה שעורים מהחלה שהיא חמץ הבאה מעשרון אחד וזה בלתי אפשר בשום פנים עם שהוא רחוק שיהיה מוגבל האורך והרוחב והעובי כי הכמות בזה יתחלף לפי קושי הבצק ורכותו וחשיבות התבואה והעדר חשיבותה ולזה הוא מבואר שהרצון בקרנותיו הוא כמו שפירשנו אנחנו עם שזה הוא יותר נאות מצד הלשון והנה היה זה הלחם דק וזה היה סבה אל שיכול להאפות כשיכניסוהו עם דפוס בלתי הם בתנור קטן כמו שנתבאר במנחות ולדקות זאת החלה יתכן גם כן שיקרא זזה הלחם לחם הפנים כי הוא זה כלו פנים ר"ל שאין לו תוך שלא ישלט בו האויר בקלות או חום התנור והנה היו משימים מאלו החלות שש במערכת האחת והיה גבהם י"ב טפחים וישאר ריוח בין שתי המערכות טפחים ושם היו נותנים שתים כפות מלאות לבונה כמו שיתבאר בפרשת אמור אל הכהנים:
@31 **ועשית מנורת זהב טהור מקשה.** ר"ל שתלקח חתיכה אחת מזהב ויקיש בה הקורנס עד שתהיה בזאת התמונה אשר זכר:
@31 **ירכה.** הוא המקום שיצאו ממנו רגלי המנורה והם שלשה כי לא תוכל לעמוד בזולת זה ובפחות מזה המספר מהרגלים:
@31 **וקנה.** הוא הקנה האמצעי אשר יצאו ממנה כל קני המנורה:
@31 **גביעיה.** הם בצורת ביצה ששני ראשיה חדין:
@31 **ופרחיה.** הם כצורות פרחי הצמחים והם כמו קערה ששפתה כפולה לחוץ ואמר שזה כולו היה מחתיכה אחת לא מחלקים נפרדים:
@32 **וששה קנים יוצאים.** מצדי קני המנורה האמצעי:
@32 **שלשה קני מנורה מצדה הא' ושלשה קני מנורה מצדה השני.** וזה היה באופן הסתעפות הסעיפים מצמרת האילן ובכל אחד מאלו הקנים היו שלשה גביעים שוליהם לצד יציאתו מקנה המנורה ואחריהם היה בו כפתור ואחר הכפתור פרח והיה שרשו לצד יציאתו מקנה המנורה:
@34 **ובמנורה.** ר"ל בגופה היו ארבעה גביעים רשני כפתורים ושני פרחים מלבד שלשה כפתורים שהיו בה במקום תוצאות ששה הקנים והנה היו מהם בקנה האמצעי למעלה מתוצאו' ששה הקנים שלשה גביעים וכפתור ופרח שהיה בגוף המנורה למעלה מתוצאות ששת הקנים ועוד היה שם פרח נוסף שהוא למטה אצל הרגלים שנאמר בפרשת בהעלותך עד ירכה עד פרחה. למדנו שאצל ירכה היה שם פרח למטה במקום תוצאת רגלי המנורה ולזה אמר עד פרחה שהוא בסוף ירכה וזה מובאר מאד ובגוף הקנים בראשם תעשה שבעה נרות ישימו בהם השמן ולא זכר בהם שיהיו זהב טהור כי הם מגוף המנורה שהיתה זהב טהור ויהיו הנרות באופן שכאשר ידליק נרותיה יאירו הנרות אל עבר פניה והנה לא התבאר בזה המקום לאיזה צד היו פני המנורה וממה שהתבאר מצורתה יתבאר שאין לה מצד עצמה פנים ואחור כי היא מתדמה משני צדדיה ואולם מצד צד הדלקתה ימצא לה פנים ואחור כי אל עבר מה שיאיר הנר יהיו פניה וזה מבואר בנפשו ואולם צד הדלקתה הוא לצד קדש הקדשים ר"ל שראשי הפתילות הדולקות היו לצד המערב שנאמר בפרשת תצוה יערוך אותו אהרן ובניו מערב עד בקר לפני יי' ר"ל שעריכת הנרות היתה לפני יי' והוא לצד המערב שבו קדש הקדשים והנה פני המנורה הוא הנר האמצעי כי הוא יוצא מעצם קנה המנורה ואולם הקנים אשר משני צדדיו הם הימין והשמאל אשר למנורה והנה ימין המנורה היה לצד הצפון והנה ראש פתילת הקנה האמצעי היה לצד המערב שהוא לצד קדש הקדשים וראשי הפתילות ששת הקנים היו נוטים אל עבר ראש פתילת הקנה באופן שיהיו כלם מאירים אל עבר פניה:
@38 **ומלקחיה.** הם צבתים לקחת בהם הפתילות ולתקנם בנרות המנורה כראוי טנאליי"ס בלעז:
@38 **ומחתותיה.** הם כצורת כפות קטנות לחתות בהם האפר שבנר ובהם היו מסירים השמן הנשאר בנר בעת הטבת הנרות וזכרה התורה שאלו המלקחים והמחתות זהב טהור לא יהיה בו סיגים:
@39 **ככר זהב טהור יעשה.** את המנורה את כל הכלים האלה הדבקים בה כמו נרותיה וששת הקנים וגביעיה וכפתוריה ופרחיה ואולם המלקחים והמחתות אינם מכלל הככר כי לא יצטרך לומר שיהיו זהב טהור כי כבר הודיע זה במה שאמר כבר זהב טהור יעשה אותה את כל הכלים האלה ובהיות הענין כן הוא מבואר שאין המלקחים והמחתות מכלל הככר וכבר נתבאר לרבותינו מהחוש שגובה המנורה היה שלש אמות ואולם התור' לא הגבילה גבהה ועוביה ורחבה אבל הגבילה משקלה לבד:
@40 **וראה ועשה כתבניתם אשר אתה מראה בהר.** מגיד שהוא מחוייב לעשות אותה בזה התבנית אבל לא חוייב העשותה מזהב אבל יחוייב לעשותה ממתכת בדרך שתהיה מקשה ואם היתה ממתכת איזה שיהיה יחוייב שיהיה נקי מסיגים כי גם בזהב דקדקה התורה בזה שנאמר זב טהור ואם לא היתה מזהב לא יחוייב היותה באה מככר כי אין המשקל מהתבנית עם שכבר יתחלף בזה כמות חומר המנורה להתחלף משקלי המתכות וכן ראוי שתבין הענין כשלחן וכליו וביתר הענינים הנזכרים שלא בא הצווי בהם שיהיה מזהב אלא למצוה אבל מה שיחוייב הוא העשותם בזה התבנית הנזכר ומזה יתבאר שהגביעים והכפתורים והפרחים לא יצטרכו בשלא תעשה המנור' מזהב כי אינם מתבנית המנורה במה שהיא מנורה. ואולם כשהיתה באה מזהב צותה התורה שתהיה בזה התואר כי אז תשלם ההערה במה שהעירה התורה בהם כמו שיתבאר מדברינו במה שיבא בג"ה ואיך שהיתה המנור' הוא מבואר שצריך שיהיו הקנים והנרות בזה התואר הנזכר כי הם מתבנית המנורה במה שהיא מנורה:
@41 **שש משזר.** הוא מהפשתן הנבחר שבארץ מצרים שהיה חוטו כפול ששה ולפי שהיריעות היו נעשות משש משזר ותכלת וארגמן ותולעת שני הנה היה ראוי שיהיה חוטי השלשה מינים הנשארים כפולים ששה שאם לא היה הענין כן לא תהיה המלאכה מתדמה ומסכמת קצתם לקצת:
@41 **כרובים מעשה חושב.** ר"ל שבאריגתה היו נרשמות בה צורות כרובים משני צדדיה כי כן תהיינה הצורות הנעשות באריגה מעשה חושב ואולי נקרא חושב כי הוא חושב מספר החוטים באופן שתרשם הצורה באריגתו:
@44 **מקצה בחוברת.** ר"ל מהקצה שלה שתתחבר בו בלולאות ובקרסי הזהב עם קצה החמש יריעות השניות המחוברות אחת אל אחת והנה חמשים קרסי זהב ישימו עשר היריעות מחוברות באופן שהיה המשכן אחד:
@47 **יריעות עזים.** הם עשויות מצמר הרך שאצל שרשי שער העזים:
@52 **וסרח העודף.** הרצון בו היתרון העודף:
@55 והנה יתבאר הרצון בזה אחר שיתבאר מענין קרשי המשכן כמה היו עבים. ויתבאר שיעור מקום קדש הקדשי' והנה יראה כי שעור מקום קדש הקדשי' היה עשר אמות אורך ועשר אמות רוחב ועשר אמות היה קומתו כקומת הקרשים ואמנם שרחבו היה עשר אמות יתבאר מאורך היריעות שהיה שלשים אמה והיה מהם עשר אמות ברוחב המשכן ויותר על זה העובי הקרשים והיה נתלה מהם לצדדי המשכן כשיעור קומתו פחות עובי הקרשים ותהיינה היריעות מגיעות לארץ לא יחסר כי אם עובי הקרשים ואמנם שארכו היה עשר אמות יתבאר מהיריעות העשרה שהיה שיעור מ' אמה שהיה נכנס מהם שלשים אמה לאורך המשכן וישאירו עשר אמות פחות עובי הקרשים שיהיה נתלה על אחורי המשכן ולפי שהפרכת היתה כנגד קרסי הזהב יתבאר שמקום הקדש היה אורכו ועשרים אמה וישאר ארך מקום קדש הקדשים עשר אמות ואולם כמה היה עובי הקרשים והנה יראה מדברי רז"ל שעבים היה אמה אלא שאם היה הענין כן לא יתכן שישאו ארבעי' ושמונה קרשים באלו ד' עגלות צב שהיו נושאות אותם עם יתר הענינים הנלוים להם שהוא ביד בני מררי כמו שיתבאר בפרשת נשא. והנכון בעיני לפי הפשט שלא היה עובי הקרשים כל זה השיעור אלא שכבר יקשה מה שאמר ולירכתי המשכן ימה תעשה ששה קרשים ושני קרשים תעשה למקצעו' המשכן שכבר יראה מזה שהיו לפאת מערב ח' קרשים וכבר הגביל שיעור הקרשים בראש הפרשה שכבר היה רחבם אמה וחצי האמה ולזה ידמה שיהיה הרחב שתים עשרה אמה וישארו שתים אמות לרחב הקרשים והנה התיר זה הספק החכם א"ע במה שאמר כי אמרו ושני קרשים תעשה וגומ' אינם בשיעור שאר הקרשים ולזה הפרידם מבין שאר הקרשים והנה כאשר כפל היריעה הששית אל מול פני האהל לפאת מזרח ישאר עד מקום קרסי הנחשת כ"ב אמה ולזה יהיו קרסי הנחשת שתים אמות בתוך קדש הקדשי' ולפי זה הפירוש תסרח חצי היריעה העודפת על אחורי המשכן לא יחסר מזה רק עובי הקרשים ותהיה פחות מחציה על הארץ ואם נודה שעובי הקרשים היה אמה שלמה לא יהיה נתלה ממנה על הארץ כי אם אמה ולזה יהיה הפירוש אמרו חצי היריעה העודפת לא שיהיה חציה בכוון והנה יקרא החלק חצי אמר יחצוהו בין כנענים. עד צואר יחצה. והנה היריעות התחתונות לא היו מגיעות עד הארץ אבל היה חסר מזה אמר וכמו עובי הקרשים כי לא היה אורך היריעות כי אם כ"ח אמה וכשהוצאנו מהם עשר אמות שהיה רחב המשכן ועובי הקרשים נשארו תשע אמות פחות עובי הקרשים לכל אחד מהצדדים לכסות הקרשים ויריעות עזים היו מוסיפות על זה אמה מזה ואמה מזה כי כבר היה ארכם שלשים אמה ועשית מכסה לאהל עורות אלים מאדמים למחסה ולמסתור ועל זה המכסה היה מכסה אחר של עורות תחשי' מלמעלה לכסו' עורות האילים והיה זה לתוספת שמירה מזרם וממטר. שלא תתלכלכנה היריעות:
@55 **עצי שטים עומדים.** ר"ל שתהיה קומתם לאורך העצים:
@57 **משולבות.** הנה היו למטה בכל קרש וקרש כדמות שתי יתדות הם כדמות שליבות הסולם והם היו נכנסות בתוך אדני הכסף שהיה ככר בכל אדן מהם לשמור שלא יבלו ראשי הקרשים בארץ וכדי שיהיה בנין המשכן יותר חזק ואלו השליבות היו מכוונות כלם אשה אל אחותה באופן שכאשר יכנסו תוך האדנים יהיו האדנים כולם מכוונים בקו אחד:
@64 **ויהיו תואמים מלמטה.** ר"ל שיהיו הקרשים אמר למקצועות המשכן למטה מכוונים ביושר ומחוברים בקרשי שתי הרוחות יחד ויחדיו יהיו כלים על ראשי הקרשים מלמעלה בדרך שיהיו מחוברים מכל הצדדים ויסכימו לשטוחי שתי הרוחות אשר הם זויות לו ולא יוסיף בקומה אחד מהם אל האחר ויכלו אל הטבעת האחד שתהיה מכונת בהם כנגד הטבעות שבכל רוח אשר בקרשים כי כבר היו בכל קרש וקרש טבעות יכנסו בהם בריחים לקשור הקרשים בדרך שיהיה האהל חזק והנה הטבעת אשר במקצועות לרוח צפון ודרום יקשור הכותל המערבי עם כותלי צפון ודרום ואלו הטבעות היו מחוץ כי ההשתדלות היה בזה הבנין שיהיה יפה מבפנים כמו שיראה מענינו:
@64 **כן יהיה לשניהם לשני המקצועות יהיו.** ר"ל שלשני הרוחות יהיו הטבעות בקרשים המקצועות עם שאר הקרשים אשר לפאת מערב והשני לרוח צפון במקצוע הצפון או לרוח הדרומי והנה הטבעות הם דבקים דבוק חזק בקרשים והם בלתי נפרדים מהם כדי שיתקיים בהם האהל כשנכנסו בהם הבריחים:
@66 **ועשית בריחים עצי שטים חמשה וגו'.** פירשו רז"ל במלאכת המשכן שהחמשה בריחים לא היו אלא שלשה אלא שהבריח העליון והתחתון היה כל א' מהם מב' חתיכות זה מבריח מקצה הכותל עד אמצעו וזה מבריח מקצה הכותל השני עד אמצעו עד שמגיעים זה לזה וידמה לפי זה הפירוש שבקרש האמצעי היו שתי טבעות כדי שיקשור הקרש ההוא שני הבריחים ואולם הבריח האמצעי היה מבריח מן הקצה אל הקצה ולזה לא היה כי אם אחד לבד ואמרו כי הבריח התיכון לא היה נכנס בטבעות אבל היו הקרשים נקובים והוא נכנס בתוכם ואם היה הענין כן הנה היה הבריח התיכון המערבי לא יתכן שיהיה מכוון כנגד הבריח התיכון הצפוני והדרומי אבל יהיה למעלה מהם או למטה ואפשר שיהיה הבריח התיכון נכנס ג"כ מטבעות ויהיה אמרו בתוך הקרשים שהוא באמצע הקרשי' וכמוהו אמרו ופעמוני זהב בתוכם סביב שהרצון בו שהפעמונים היו בין הרמונים כמו שאמ' פעמון זהב ורמון פעמון זהב ורמון לא שיהיו הפעמונים תוך הרמונים בעצמם וכבר זכר זה א"ע. והנה בזה האופן יקימו המשכן באופן שיהיה בנינו חזק ולא יתפרדו חלקיו:
@71 **ועשית פרוכ'.** הנה יתב' לך כי מלאכת הפרוכ' היא כמלאכ' יריעות המשכן כי כל אחת היתה מכ"ד חוטים שש לפשתן וכן לתכלת וארגמן ותולעת שי וכל אחת היתה נעשת מעשה חושב באופן שיהיו נראים שם ראשי הכרובים משני הצדדי' ואמנם היה הבדל ביניהם מצד הוראת הגדר כי כשהיתה המלאכה עבה מאד נקראת פרוכת ואמרו ז"ל שהפרוכת עבה טפה וראש הפרוכת היה כרוך במוט והיו שם ארבעה עמודים ששם היו נסמכים על ארבעה אדני כסף והיה בראשם ווים של זהב והם כמו יתדות עקומים והיו מחזיקים במוט שהפרוכת כרוך בו והנה הפרוכת היה תחת קרסי זהב והוא היה מחיצה מבדלת בין הקדש ובין קדש הקדשים ושעירו הפרוכת היה עשר אמות על עשר אמו' ומבית לפרכת היה הארון והכפורת ומחוץ לפרכת היה השלחן על צלע צפון והמנורה על צלע דרום:
@76 **ועשית מסך לפתח האהל.** הנה זה המסך היה לפאת מזרח והיה כמו מחיצה ומעשרים וארבעה חוטין היה נעשה מארבע מינים שנעשו מהם הפרוכת ולא היו בהם כרובים ולא היו מעשה חושב אבל מעשה רוקם. והרצון בזה שהצורה הנעשת בו אינה נראת כי אם מצד אחד. ואחשוב כי הצורה הנעשת בו היתה נראת מבפנים וראש המסך היה כרוך במוט והיו שם ח' עמודי שנים שהיו נסמכים על חמשה אדני נחשת והיה ראשם ווים של זהב והיו מחזיקים במוט שהמסך כרוך בו:
@78 **ועשית את המזבח עצי שטים.** הוא מזבח החיצון ואולם מזבח הקטרת יבא זכרונם במה שאחר זה והמזבח הנעשה בידי משה היה ארכו חמש אמות ורחבו חמש אמות רבוע יהיה המזבח יתבאר מזה שלא הקפידה התורה שיהיה ה' אמות ארכו ורחבו ה' שאם היה הענין כן הנה יהיה אמרו רבוע יהיה המזבח מותר ואמנם הקפידה התורה שיהיה רבוע ושיהיה קומתו שלש אמות שהוא כשיעור קומת האדם ובעבור שמצאנו במזבח שעשה שלמה שהיתה קומתו עשר אמות ידענו שאלו הג' אמות אינם קומת המזבח בכללה ואולם זאת הקומה היא מכרכוב המזבח עד מקום המערכה והנה הכרכוב הוא הסובב ולמטה ממנו היה חצי קומת המזבח כמו שיתבאר אחר זה שנאמ' ונתת אותו תחת כרכוב המזבח מלמטה והיתה הרשת עד חצי המזבח. ולמטה היה יסוד המזבח הנזכר בפרשת ויקרא וכאשר התישב שגובה המזבח היה יותר משלש אמות הנה יחוייב שנאמר שמה שאמרה התורה ושלש אמות קומתו הוא ללמד שאם לא היתה קומתו כי אם שלש אמות כשר:
@79 **ועשית קרנותיו על ארבע פנותיו.** הנה היו הקרנות ארבע. בארבעה זויות מקום המערכת והנה לא נזכר שעור אלו הקרנות בתורה והיה שיעורם בבית שני אמה על אמה:
@79 **ממנו תהיין קרנותיו.** למדנו מזה שאין ראוי לעשות הקרנות לבדם נפרדים ומונחים במזבח אבל ראוי שיהיה הקרנות מגוף המזבח. וראוי שתדע שהמזבח שאין בו ארבע קרנות פסול שנאמר בפרשת ויקרא ונתן על קרנות מזבח העולה וכן אם אין לו יסוד שנאמר ונתן אל יסוד מזבח העולה וכן אם אינו מרובע שנאמר רבוע יהיה המזבח וכן אם אין לו כבש שנאמר לא תעלה במעלות על מזבחי למד שראוי שיהיה באופן שנוכל לעלות בו לא במעלות ומה שזה דרכו הוא כבש ובכלל מפני שהוא מחוייב שתהיה קומתו ג' אמות הנה אי אפשר מזולת כבש לעלות עליו לערוך הנתחים על העצים אשר על האש כמו שנזכר בפרשת ויקרא ואולם שעור ארכו ורחבו אין מעכבים כיון שהוא מרובע ובלבד שלא יפחות מאמה על אמה כי לא מצאנו מזבח פחות מזה השעור וזה כי מזבח הזהב היה שיעורו אמה על אמה ועוד כי נתחי הפר לא יכילם מקום יותר קטן מאמה על אמה ואף על פי שיושמו זה על זה והנה הוא ראוי שיהיה המזבח באופן שיהיה ראוי להקרבת כל הקרבנות:
@80 **ועשית סירותיו לדשנו.** ר"ל להשים בהם דשן המזבח להסירו משם והנה צורת הסירות ידועה:
@80 **ויעיו.** הם מגרפות לגרוף בהם הדשן לשומו בסירות:
@80 **מזרקותיו.** הם כלים צורתם ידועה והיו מקבלים בהם דם הקרבנות:
@80 **ומזלגותיו.** ומתתותיו הם כלים בעלי יתדות עקומות להפך בהם הבשר על גחלי המערכה לערכו כראוי:
@80 **מחתותיו.** הם כדמות כפות גדולות היה להם בית יד היו לוקחים בהם נחלי אש לשאת אותם למזבח הקטרת כמו שיתבאר:
@80 **לכל כליו.** הוא כמו כל כליו והלמ"ד נוספת:
@81 **מכבר מעשה רשת נחשת.** ר"ל שיעשה מנחשת כדמו' כברה שיהיה נקוב כמו הרשת ועל הרשת היו ארבע טבעות נחשת לשום בהם הבדים לשאת המזבח והנה המכבר היה דבק למזבח בלתי מתפרד ממנו באופן שכאשר ישימו בבדים בארבע טבעות ישאו עמו המזבח והוא היה נתון תחת הסובב והיה מגיע עד חצי קומת המזבח היה להבדיל בין הדמים הנתונים למעלה כמו דם החטאת ובין הדמים הנתונים למטה כמו דם העולה ומה שידמה לו בזה:
@85 **נבוב לוחות תעשה אותו.** ר"ל שזה המזבח נעשה מלוחות עצי שטים והיה חלול כמו תיבה ומה שידמה לה והיה זה גם כן מפני היותו מטלטל ואחר שבאו אל המנוחה ואל הנחלה עשו המזבח מהאבנים בלתי חלול והוא מה שאמרה התרה אבנים שלמות תבנה את מזבח יי' אלהיך וזה תאר המזבח שעשו בבית שני ע"פ הנביאים ומלנו תעמוד על צורת זה המזבח הנזכר בזה המקום בנו בנין אבנים בארץ מרובע היה ארכו ורחבו ל"ב אמה ועלה הבנין ה' טפחים ואח"כ כנסו ה' טפחים והגביהו הבנין ה' אמות והיה ארכו ורחבו ל' אמות וב' טפחים וה' טפחים העודפים סביב יסוד הבנין הם יסוד המזבח ואחר כך כנסו ה' טפחים אחרים וזהו סובב והגביהו הבנין ג' אמות והיה ארכו ורחבו כ"ח אמות וה' טפחים והוא מקום המערכה ובכל זוית וזוית עשו קרן גבוהה ה' טפחים וארכו אמה ורחבו אמה והם קרנות ולפאת דרום המזבח עשו כבש לעלות אל המזבח ואל הסובב והנה לא נזכר בתורה מקום הבש והנה נודע זה מפי הנביאים כמו שאמר דוד הכל בכתב מיד יי' עלי השכיל וכבר יתבאר זה באופן מה מדברי התורה וזה כי מפני ששחיטת קדשי הקדשים בצפון הנה ראוי שיהיה הכבש בדרום כדי שיהיה המזבח כנגד קדשים הקדשים ולפי שלפני המזבח אין ראוי שיהיה לצד המערב כדי שלא יהיו אחוריהם כנגד היכל יי' בעלותם שם הנה יחוייב שיהיו לצד הדרום כי הדרום יותר נכבד מהצפון ולזה היתה המנורה בדרום:
@85 **ואולם** רגלי הכבש אי אפשר שיהיו לצד המערב לסבה שזכרנו ולא לצד המזרח שאם היה הענין כן היה ההעתק מהכבש למזבח בהפך הנהוג מתנועת הרגלים בעליה וזה שהוא ראוי שתהיה התנועה בה מפאת המערב כי זה מה שיורה על ההתרחק מהש' ית' והוא הפך מה שכוון בזאת העבודה ולזה יחוייב אם הונח הענין על זה התאר שיהפוך עצמו העולה בכבש תכף אחר עלייתו להפך הצד אשר היה פונה אליו בעלותו וזה כלו בלתי נהוג ובלתי מורגל עם שהפכוה להפך הצד אשר היה פונה אליו בעלותו מורה ההתרחק מהשם יתעלה והוא מבואר שאין ראוי בתנועה האחת שיקביל קצתה לקצת כל שכן בזה הבנין הנכבד ולזה יחוייב שיהיו רגלי הכבש לפאת דרום:
@86 **ועשית את הצד המשכן.** ר"ל החצר שהיה מקיף במשכן והנה אורך המשכן שהיה ל' אמה אורך י' אמות רחב והחצר היה ארכו ק' אמה ורחבו נ' אמה וכאשר תשים רוחב המשכן באמצע רחב החצר ישארו עשרים אמה לפאת צפון ועשי' אמה לפאת דרום וידמה שכ' אמה גם כן היו נשארים לחצר המשכן לפאת מערב בדרך שיהיה רוחב החצר לשלש צדדיו שוה וישארו חמשים אמה לפאת מזרח שהיו להם המזבח החיצון ולזדה היה מקום המזבח החיצון מרובע ורחבו נ' אמה על נ' אמ' וזה הוציאו רבותנו ממה שאמר ורוחב נ' בנ' ר"ל שבנ' אמה מארך החצר היה כלה המשכן שאם לא היה הענין כן לא היה ראוי שיא' כי אם רוחב חמשים:
@86 **קלעים.** הם כדמות יריעות ולא היו כי אם מששה חוטים והיו מן הפשתן שנאמר שש משזר:
@87 **ועמדיו עשרים.** לכל חמש אמה עמוד אחד והעמודים ההם היו נסמכים על אדני נחשת ובראשם היו ווים של כסף להחזיק בקלעים ואחר כן היו חוטי כסף דבקים בעמודים לקשור בהם הקלעים לעמודים בדרך שלא תפרידם הרוח מהם ואלו החוטים היו במקומות רבים מהעמודים לפי מה שאחשוב באופן שיקשרו הקלעים בעמודים ויתקיימו בהם ורוחב חמשים בחמשים רוצה לומר שכבר נמצא רחב החצר נ' אמה בנ' אמה מהאורך שהיה חוץ למשכן ואולם במקום המשכן לא היה רחבו כי אם כ' אמה לצד צפון וכ' אמה לצד דרום כמו שביארנו וקומה חמש אמות שש משזר ר"ל שהקלעים היתה קומתו חמש אמות לכל כלי המשכן בכל עבודתו ר"ל כל הכלי' שהיו צריכים בהקמתו ובהורדתו כמו מקבות להכות בבדים להכניסם בטבעות ולהוציא העמודים מתוך האדנים ויתידות להוציא הבדים מתוםך הטבעות ולנעוץ בקרקע בשער החצר ואז יניחו הקלעים סביבם וישימו שם עמודיהם ואדניהם ואחר זה יסירו היתדות ההם משם והנה כל אלו הכלים היו מנחשת ואף על פי שכלי המשכן היו כלם מצופים זהב או כס הנה המשרתים להם ראוי שיהיו למטה ממדרגתם ולזה הושם מנחשת. הנה זה ביאור המלות וקצת דברי זאת הפרשה. ואולם שאר הדברים אשר באו בה הם מבוארים עם מה שהישרנו אליו ואולם התועלות המגיעות הם רבים:

@1 **ביאור דברי הפרשה:**
@1 **התועלת** הראשון הוא במצות והוא מה שצוה לעשות מקדש לשם יתעלה שנאמר ועשו לי מקדש והוא בניין יחוייב שיהיה בו בקדש הקדשים וקדש ואולם יהיה בקדש הקדשים הארון אשר בו היו הלוחות ובקדש יהיה השלחן ומנורה ומזבח הקטרת על התבנית שהתבאר בתורה ותהיה שם גם כן עזרה היה בה מזבח העולה לפי התבנית הנזכר בתורה ויתר הדברים שהתבאר מהתורה שאי אפשר למקדש מזולתם. ואולם התועלות המגיעות מזאת המצוה נפריד להם מאמר אחד מנותני שרשי המצוה הזאת ואולם שרשי המצוה הזאת הם י"ב:
@1 **השרש** הראשון הוא שבנין בית המקד' וכליו צריך שיהיה לשם השם יתע' שנאמר ועשו לי מקדש ואם לא נעשה לשמו יתעלה נפסל אותו דבר שלא נעשה לשמו. ולזה דקדק בספר מלכים בזה כמו שביארנו שם כבר נתבאר זה השרש במקומותיו:
@1 **השרש** השני הוא ששיעור בית המקדש ושעורי חלקיו הנזכר בתורה לא היה כי אם למקדש ההוא שנעשה במדבר ואולם התבנית יחוייב שיהיה נוהג לדורות שנאמ' ככל אשר אני מראה אותך בהר את תבנית המשכן ואת תבנית כל כליו וכן תעשו והוא מבואר שאין השעור מהתבנית כי כבר יהיה התבנית שמור עם התחלפות כמו השעור ולזה תמצא שעורי המקדש שבנה שלמה מתחלפים לשעורי המקדש שבנה משה וכן מה שצוה שיהיו קצת הדברים מעצי השטים לא היה גם כן אלא לפי שעה והיה זה אז בזה האופן לפי היה זה המקדש מטלטל ולזה אמר כי לא באתם עד עתה אל המנוחה ואל הנחלה. ואולם נשלמה הביאה אל המנוחה ולא הנחלה כשנגלה בית עולמים לדוד וכבר נתבאר זה השרש ברבעה עשר מזבחים ובראשון מחגיגה:
@1 **השרש** השלישי הוא שאין עושין שעור המקדש ושעור חלקיו כי אם על פי נביא ולזה תמצא שהמקדש שבנה שלמה היו כל שעוריו מוגבלים על פי נביא שנאמר הכל בכתב מיד השם עלי השכיל וצריך גם כן שיהיה שם מלך וכהן וסנהדרין כמו הענין במשכן שעשה משה ובמקדש שבנה שלמה וזה יתבאר ממה שאמר בכל אשר אני מראה אותך בהר את תבני' המשכן ואת תבנית כל כליו וכן תעשו. רוצה לומר שיהיה לכם זה מראה ממני כמו שהראתי למשה ולפי שאמר אותך והיה מבואר כי משה היה נביא ומלך וכהן גדול כי הוא היה אני הכהונה והוא היה ראש סנהדרין והיה בכל אחד מאלו התארים הושם בזה הענין וזה כי הנביא הוא מיוחד בזה המראה שהוא מהשם יתע' והמלך הוא שליט בדברים הכוללים המשותפים לכל ישראל ועל פיו ראוי שיבנה כמו הענין במשכן משה רבינו ובמקדש שלמה והכהן עם שהוא משותף לכל ישראל הנה הוא השליט בזה הבית והסנהדרין הם כוללים גם כן ומשותפין ליש' ועל פיהם יהיו כל הדברים הגדולים ולזה גם כן יחוייב שלא יוסיפו על שעור ירושלם ועל בית המקדש אלא על פי אלו התנאים ואולם השעורים שהיו בבית שעשה שלמה על פי נביא יהיו מוגבלים בבית המקדש שיבנה אחר זה ואף על פי שלא יהיה על פי נביא וזה מבואר מאד ולזה בנו בני הגולה בית שני לפי השעורים שהיו בבית שלמה וכבר נתבאר זה השרש בשני משבועות ובראשון מסנהדרין:
@1 **השרש** הרביעי הוא שבית המקדש אחר שנגלה מקומו יחוייב שיהיה נבנה מאבנים יקרות אבני גזית או במה שידמה להם שיהיה רב הקיום להורות על קיום השם יתע' וזה דבר נלמדהו מבנין שלמה שהיה על פי נביא והיה בעינו בזה התאר ואפשר גם כן שנלמד זה ממזבח החיצון שצותה התורה שיבנוהו אבנים שלמות אחר בואם אל המנוחה ואל הנחלה והיה מעצי שטים בימי משה כמו הענין בקדש וקדש הקדשים ולזה יחוייב בהם שתהיינה שלמו' כי כבר יוחדו בזה אבני המזבח ולזה היו אבני גזית אבני בית המקדש שבנה שלמה אלא שלא היו נפסלות אצל המקום שנבנו בו אבל מרחוק מאד מאד שלא ישמעו קול הפוסל בבית בהבנותו שנאמר והמקבות והגרזן וכל כלי ברזל לא נשמע בבית בהבנותו להורו' על שלמות השם שיאן בעצמותו לא תוספת ולא חסרון ולזה דקדקו שיהיו האבנים הבים שם באופן שלא יהיה בהם תוספת יצטרך לפסלו. כבר נתבאר זה השרש במכילתא ומזה המקום יתבאר שאין עושין אכסדראות של עץ בכל העזרה כי הבניין ההוא הנפלא ראוי שימצא בו הקיום ולזה יחויב שיהיה מאבנים כבר נתבאר זה השרש בראשון מתמיד. ומזה המקום יתבאר עוד שאבני ההיכל והעזרות ראוי שיהיו שלמות בלא פגימה וזה שאם דקדקו בהם שלא יהיה בהם דבר נוסף בבאם שם כדי שלא יורה זה על חסרון בשעה שיראה האנשים שיצטרכו המסתתים לפסול האבנים ההם כל שכן שראוי שידקדק שלא יהיה בהם פגימה וחסרון כי זה יותר מורה על חסרון עם שזה החסרון הוא נראה בהם תמיד ולה הוא מבואר שאבני ההיכל והעזרות שנפגמו פסולות וכבר נתבאר זה בשני מתוספת מגילה ולזאת הסבה שזכרנו יחוייב שירצפו באבנים קרקע בית המקדש כדי שיתקיים החלקות בו ויהיה תמיד על משל אחד מהיופי. וזה אם נתלשה אבן מהבניין ההוא הרי היא פסולה עד שתבקע כי התורה דקדקה שלא יהיה דבר חוצץ בין רגלי הכהן העובד לבית המקד' ולזה לא סדרה התורה שיהיה לכהנים לבוש ברגליה:
@1 **השרש** הה' הוא שמצוה מן המובחר לחזק הבנין ולרומם אותו בחזקת היה וזה דבר שנלמדהו ממה שנראה מכונת התורה במה שהגבילה בבית עולמי' שיהיה נבנה מאבנים כמו שביארנו ובמה שהעידה על רוממות המשכן ויפיו לפי מה שאפשר במשכן שעשה משה ובמקדש שבנה שלמה וזהו אמרו ולרומם את בית אלהינו:
@1 **השרש** הו' הוא שאין בונין בית המקדש בלילה וזה מבואר מהשרשים הכוללים ולזה אמר בספר עזרא והיה הלילה לנו למשמר והיום למלאכה וזה היה ראוי כדי שתהיה מלאכתו יותר שלמה:
@1 **השרש** השביעי הוא שאין בנין בית המקדש דוחה שבת והיה זה כן כי התורה לא הגבילה זמן בנינו וכבר נתבאר זה השרש בשני משבועות:
@1 **השרש** השמיני הוא שהכלים שהיו במשכן ממתכת כגון המנורה וכליה והשלחן וכליו ומזבח הקטרת וכלי השרת אין עושין אותו אלא ממתכת ולזה תמצאם גם כן ממתכת בבנין שלמה ולזה יתבאר שאם נעשו מזולת מתכת פסולין וכבר נתבאר זה השרש בחמישי מסוכה:
@1 **השרש** התשיעי הוא שקשות השלחן היו ארבעה סניפין של זהב והיו מפוצלין מראשיהן והיו מונחין שנים שנים בצלעות ארך השלחן במקום יוכנו לסמוך בהם המערכות של לחם הפנים והמנקיות היו י"ד לכל אחד משתי המערכות ושני כפות היו שם שהיו מניחים שם הלבונה אצל המערכות והקערות היו דפוסים שהיו אופים בהם לחם הפנים ומניחים אותן בהם אחר אפיתן והנה מניין אלו הכלי' ותמונתם הוא ממה שעמדו עליו מן החוש וכבר התבא' זה השרש באחד עשר ממנחו':
@1 **השרש** העשירי הוא שגביעי המנור' וכפתוריה ופרחיה הם מעכבין זה את זה והנה מספרם לפי מה שהגבילה התורה מ"ב ואם חסר אחד מהם פסולה וזה כלו הוא כשבא' מן הזהב ואז ג"כ יחוייב היותה מככר זהב טהור והמלקחי' והמחתו' וכלי שמנה אינן מכלל הככר כמו שביארנו במה שקד' וכבר ביארנו שאינו מחוייב היותר מזהב כי אין החומ' אשר ממנו יהיה הדבר מהתבנית והתורה לא חייבה אלא שיעשו אלו הדברי' הנזכרים התורה ואם לא היתה באה מהזהב אז לא יחויב שיהיה משקלה ככר כי אין המשקל מהתבנית אבל עכ"פ יחוייב שיהיה מקשה אחת כי זה שוה בכל מתכת. והנה התורה דקדקה בזה שתהיה מקשה איך שהיתה שנאמר מקשה תעשה המנורה. ולזה כפל המאמר בזה ואמר כלה מקשה אחת זהב טהור. ולא יחוייב גם כן כשלא היתה מזהב שיהיו בה גביעים וכפתורים ופרחים כי אינם מהתבנית למנורה במה שהיא מנורה. ואמנם מספר קני המנורה ונרותיה הם מתבנית המנורה במה שהיא מנורה ולזה יתבאר שאם שנה מספרם פסולה לפי שכבר שנה התבנית וכבר נתבאר זה השרש בשלישי ובעשירי ממנחות:
@1 **השרש** הי"א הוא שנרות המערכה היו כנגד רחב הבית בין צפון ובין דרום וזה מבואר מכח דברינו במה שקדם והשלחן היה ארכו לארך הבית חוץ מהארון שהיה ארכו לרחב קדש הקדשים וזה עם שהוא ראוי להיותו כן כבר הושג זה בחוש לאשר ראו בית המקדש והם ז"ל ספרו שהם ראו שכן היה כבר נזכר זה בי"א ממנחות:
@1 **השרש** הי"ב והוא שהדבר שהם מתבנית המזבח והם רבועו ויסודו וקרנותיו והכבש הם מעכבים כי כל אלו הדברים עצמיים במזבח לפי מה שזכרה התורה בענין הקרבנות ובזה המקום ובסוף פרשת וישמע יתרו ואולם שעורי האורך והקומה אינם מהתבנית ולזה אינם מעכבים אם לא היו בשיעור שהגבילה התורה או אם לא היו בשיעור שעשה שלמה ובני הגולה והוא שיהיה ג' אמות קומתו כנגד גובה המערכה כי התור' אמר רבוע יהיה ושלש אמו' קומתו ולזה יתבאר שעכ"פ צריך שיהיה רבוע כי אם לא היה זה לעכב לא נצרך לומר רבוע יהיה שהרי אמר חמש אמו' אורך וחמש אמות רוחב ולפי שהפריד המאמר בין שיעורי הארך והרחב ובין שיעורי הקומה במה שאמ' רבוע יהיה שהוא לעכב למדנו מזה שמה שאמר בשלש אמות קומתו שהוא לעכב הנה דקדקה התורה בה לפי שקומת האדם הבינוני הוא שלש אמות וראוי גם כן שלא יהיה רחבו פחות מאמה על אמה אורך כי לא נמצא שיעור קטן מזה בשום מזבח וזה כי מזבח הקטרת היה אמה על אמה ועוד כי בפחות מזה השיעור לא יכול נתחי הקרבנות אשר יקריבו עליו כבר נתבאר זה בששי ובי"ג מזבחים ובשלישי מסוכה:
@1 **השרש** הי"ג הוא שהמזבח שהיה חסר מבנינו פסול כי התורה דקדקה באבניו יהיו שלמות בזולת פגימה להורות על שלמות השם יתעלה הנעבד בו אלא שלא בקראהו חסר באי זה חסרון היה כי האבנים השלמות לא יתכן שיהיה מהם בנין בזולת פגימה ולפי שהשיעור הקטן שמצאנו בתורה באלו הדברים הוא טפח. הנה לא יפסול המזבח אם לא היתה פגימה מבנינו טפח כבר נבתאר זה השרש בראשון מחולין. והנה שאר שרשי זאת המצוה יתבארו בג"ה וראוי שתדע כי שעורי הבית שבנה שלמה ובני הגולה ושעורי חלקי הבית הם בעצמם שעורי הבית שעתיד להבנות וכר התבאר השעורים ההם במסכת מדות ובמקומות רבים מפוזרים מהתלמוד ואין הנה מקום זכרונם כי הוא ממה שראוי שיהיה הממר בו בספר מלכים:
@1 **התועלת** השני הוא במצות והוא מה שצוה שלא יסורו הבדים מעל הארון וזהיה זה כל להורות על שלמות התורה שהיה בארון כמו שנבאר אחר זה וכבר נזכר זה בז' מיומא:
@1 **התועלת** השלישי הוא במצות. והוא מה שצוה לתת לחם הפנים על שלחן הזהב שהיה בקדש ומצותו שיהיה שם תמיד שנאמר ונתת על השלחן לחם הפנים לפני תמיד לפי שכבר נתבאר בפרשת אמור אל הכהנים שאהרן ובניו יאכלו זה הלחם ויהיה נערך על השלחן בכל שבת ושבת הנה יחוייב מזה שיהיו הם המסירים הלחם שהיה שם והמשימים אותו שם זה אצל זה באופן שתכף שיוסר הלחם שהיה בו יושם בו הלחם הנאפה מחדש ולפי שלא הגבילה התורה זמן לאפיתו ידענו שאין אפייתו דוחה שבת ולא יום טוב והנה לחם הפנים הוא דק מאד כמו שביארנו והתבאר מלשון התורה במה שיבא ויקיפו בו פנים רבים כמו שזכרנו. ולזה נקרא לחם הפנים כבר נתבאר זה בי"א ממנחות. ואום שאר שרשי זאת המצוה יתבאר בג"ה בפרשת אמור אל הכהנים ואולם התועלות המגיעי' מאלו המצות הנזכרות בזאת הפרש' הוא בדעות ובקצת תועלות גם כן בענינים המדיניים. והנה התועלת המגיע מהם בדעות קצתו משותף לכל עניני המקדש ולכל מיני העבודה הנעשי' בו וקצתו מיוחד לדבר דבר ואולם התועלת המשותף בזה הוא שזה יישיר להאמין שיש שם אלוה אדון הכל שהוא ראוי שיעבד כי מאתו הכל ולזה נחוייב לכבדו מהונינו ושהוא בתכלית הגדולה והכבוד ולזה נעשה לו זה המקד' הנפלא בנוי וטוב התקון ושהו' אחד לבד ולזה לא תהיה זאת העבודה והמקדש כ"א במקום אחד לבד וע"י משפחה מיוחדת לבד. והם זרע אהרן והלוים והתועלת המגיע בזה בעניני' המדיניים הוא כי בזה יגיע לכהנים העובדים השם יתע' תועלת בשיהיה לחמם נתן והמצטרך להם כדי שיהיו פנויים לעבודת השם יתע' ולהשגתו לפי מה שאפשר והשגת סודות התורה וביאור משפטים ולזאת הסבה גם כן היתה זאת העבודה במקום היותר נבחר להגעת השלמות והוא הר המוריה כי אליו היתה הכונה מתחלת הענין שהיה בו בית המקדש כמו שזכרנו במה שקדם. והנה הגיע בזה תועלת שיורו הכהנים להם משפטי השם יתעלה ותורתו כמו שאמר יורו משפטיך ליעקב ותורתך לישראל ואולם התועלת המגיע מזה בדעות שהוא מיוחד בדבר דבר הנה נזכור אותו מג"ה אצל המאמר אחד לאחד:
@1 **ואנחנו** מציעים בכאן הצעה תקיף באופן מה על כל אלו הדברים אשר במקדש ונאמ' שהוא מהמפורסם למי שיראה דעת הקודמים לפי מה שספר הפילוסוף מהם באלהיות ובטבעיות כי בימי משה רבינו ע"ה היתה הפילוסופיא חסרון מאד עד שלא נודע להם מהסבות כי אם הסבה החומרית ונעלמת מהם הסבה הצוריית והיה זה סבה אל שנעלמה מהם הסבה הפועלת והסבה התכליתיית. ומזה המקום נסתעפו דעות אפיקורוס וסיעתו שהיה חושב שיהיו כל הענינים נופלים במקרה מזולת סבה פועלת כלל וזה כלו היה מביא אל שנסבל חכמת הנמצאות אשר ההשגה בה היא הצלחת הנפש וזה כי אין החכמה בהם דבר יותר מידיעת הצורות והפועל והתכלית כי החומר הלקוח בגדר הוא עם צורות מה כמו שהתבאר במה שאחר הטבע והיה זה מביא גם כן אל שנכפור במציאות השם יתעלה ובהגעת הנבואה לאדם וזה ממה שאין ספק בו לפי מה שהתבונן התבוננות מה באלו הענינים ומפני זה כלו הנה כאשר רצתה התורה להישירנו אל קניין השלמות האנושי אשר אי אפשר שנקנהו אם לא בהשגת חכמת הנמצאות לפי מה שאפשר ובהשגת מציאות השם יתעלה הנה הישירה אותנו להאמין שבכאן צורות הם קצתם במדרגת השלמו' לקצת כי בזה נתישר אל השגת סודות המציאות ונאמין בכאן שיש בכאן אלוה פועל כל הנמצאות והנה החל בצורה היותר נכבדת מאלו הנמצאות השפלות והוא הנפש המדברת. ולזה סדר שיהיו שני כרובים על ארון העדות אשר בו לוחות הברית והנה הכרוב האחד הוא מעיר על השכל ההיולאני והכרוב האחר הוא מעיר על השכל הפעל אשר פניהם איש אל אחיו כמו שהבתאר בספר הנפש והתבאר זה עוד בראשון מספר מלחמות השם ולפי שיש גבוה עליהם ישתדלו בהשגתו בחזקת היד רצה שיהיו פורשי כנפים למעלה להורות על שתנועתם היא לצד המעלה כאלו ישתדלו לעלו' מזה המציאות אל מציאות יותר גבוה וזה הוא האמת כמו שיתבאר במקומותיו והנה היו בארון לוחות הברית להורות על שהגעת הנבואה איננו נמנע אבל תהיה הגעתה אפשרית באמצעות שני כרובים האלו כמו שביארנו בשני מספר מלחמות השם וזה שרש גדול ועמוד חזק לקיים הגעת התורה מהשם יתעלה בנבואה כי לולי זאת האמונה תפול התור' בכללה וכדי שנתבונן בזה ונעמוד לעל הכונה הזאת אשר בעבורה היו הכרובים על הארון בזה הא פן סבב השם יתע' בדרך מופת על ידי משה רבינו עליו השלום נביאו שבהגיע הנבואה למשה יראה על הרון רושם מוחש והואר הענן שאלו הגיעהו משם הנבואה ולזה אמר ונועדתי לך שם ודברתי אתך מעל הכפורת מבין שני הכרובים וגומ'. וכבר יתבאר לך שצורת הכרובים היא מורה על הצורות והנבדלות ממה שנזכר בספר יחזקאל מזה במעשה מרכבה וזה ממה שאין ספק למי שיתבונן בדברים ההם ולפי שזאת הצורה עם שהיא יותר גבוהה משאר הצורות אשר בכאן הנה בינה ובין שאר הצורות הבדל עצום כמו שהתבאר בספר הנפש כי שאר הצורות אשר בכאן מם היולאניות. וזאת הצורה המדברת היא נבדלת באופן מה כמו שביארנו בראשון מספר מלחמות השם הנה היתה מחיצה מבדלת בין המקום אשר היה בו ארון העדות אשר היה מורה על מציאות זאת הצורה ומציאות שאר הצורות הנבדלות ובין המקום אשר היה בו מה שהיה מורה על מציאות הצורות ההיולאניות והם השלחן והמנורה כמו שיתבאר והיה מקום ארון העדות קדש קדשים ומקום השלחן והמנורה קדש שנאמר והבדילה הפרכת לכם בין הקדש ובין קדש הקדשים והנה שם היה יותר מכרוב אחד להורות כי מהשכל ההיולאני נקח התחלת מופת שבכאן שכל אחד הוא המשלים אותנו והמוציא מהכח אל הפעל והעיר אותנו עם זה על שהשכל הפועל אינו השם יתע' אבל הוא גבוה ממנו והוא עלתו ולזה היו כנפיו פרושות למעלה וכבר ביארנו שהענין הוא כן במה שאין ספק בו בחמישי מספר מלחמות השם ואולם רוחב הארון וארכו וקומתו היה באופן שיאות לשים בו לוחות האבן עם שקומת הארון היתה שוה לקומת השלחן שהיא קומה ראויה לשלחן אשר יאכלו בו האנשים לחם והוא כשעור חצי קומת האדם והנה באה האזהרה שלא יסורו הבדים מעל הארון לפי שהארון ומה שעליו הכרובים מורה על מציאות שלם והוא מציאות התורה ומציאות הצורות הנבדלות אשר יעמידונו על מציאו' השם יתעלה שהוא בתכלית השלמות ולפי שהדבר השלם הוא מה שלא יחסר בו דבר צוה השם יתע' שלא יצטרך הארון דבר מחוץ כשיצטרך לנשאו אבל ימצאו בו דבריו מכונים והנה השלחן הוא מעיר על מציאות הנפש הזנה והמנורה על מציאות הנפש המרגשת כמו שנבאר ולהיות הנפש המרגשת יותר נכבדה היה מקום המנורה בדרום שהוא הימים ומקום השלחן בצפון כמו שנזכר בפרשת אלה פקודי והיה זה כן לפי שהימין הוא יותר נכבד מהשמאל והנה היה מקום ארון העדות במערה לפי שאם היה במזרח היה מקם לאנשים לטעות שיהיה השמש הוא האלוה או אחד משאר הכוכבים או כלם ולהרחיק מה הטעות הנפלא היה ארון במערה והנה היה מזבח הזהב אחרי השלחן והמנורה מכוון בין שניהם והוא היה במקום הקדש ואחריו היה מחוץ מזבח הנחשת והנה היו אלו המזבחות מורים על ההפסדים ושהם יהיו כשישוב המורכב אל היסודות אשר הורכב מהם ולזה היו להם ארבע קרנות במקום המערכת והיה מזבח הנחשתי מורה על הפסד הנמצאות אשר לא יהיה להם השארות נצחיי אחר המות ולזה לא היו עושים בו כי אם הקטרת הקטורת כי האד העולה מהקטרת בהקטרתו הוא יותר חזק הגשמיות מהבשמים בעצמם והיה זה כן להנקותו מהחומר המסתבך עמו בהשגת ריחו וכן הענין בנפש המדבר ר"ל כי בהפרד' מהאדם מצא יותר חזקה בפעולתה והוא ההשגה ממה שהיתה בהדקבה עם החומר להנקותה משאר כחות הנפש המונעות אותה מלהשתמש בהשגתה. ואולם מזבח הנחשת היה מור' על הפסד שאר המורכבו' וההבדל בין שני אלו ההפסדי' מבואר ולזה היה המזבח הזהב במקום הקדש והיתה מחיצה בינו ובין מזבח הנחשת כמו שהיו הכרובים המעירי' על צורת האדם במקום קדש הקדשים והשלחן והמנורה המעירים על שאר הנפשות היו במקום הקדש:
@1 **ואולם** איך יתבאר כי השלחן הוא מורה על מציאו' הנפש הזנה והמנורה על הנפש המרגשת הנה זה יתבאר לפי מה שאומר. והוא כי כבר התבאר בספר הנפש כי מפעולות הצורות נעמוד על מציאות הצורות שהם מסודרים מהם וזה כי פעולות הצורות הם יותר ידועות מהצורות בעצמם וכן נעמוד מהדברים אשר בהם תהיינה פעולות הצורות על פעולות הצורות כי הדברים הם הם יותר ידועים מפעולות הצורות. והמשל כי פעולות ההזנ' היא יותר ידועה מהנפש הזנה והנה המזון הוא יותר ידוע מפעולות ההזנה ולזה נקח ראיה מהמזון על מציאות הנפש הזה ומהמראים על הכח הרואה ולזה הושם בשלחן הלחם שהוא המזון היותר כולל לבעלי הנפשות והושם במנורה האור שהוא המראה היותר מוחש עד שכבר ישים אר הדברים נראים ומה שישים זולתו בתאר מה הנה הוא ראוי התאר ההוא כמו שהתבאר זה במקומותיו ולהיו' הראות הנכבד שבחלקי הנפש המרגשת עד שהוא הולך במדרגת השלמות מהם באופן מה הנה העירה התורה עליו להורות על מציאות הנפש המרגשת והנה הורה הלחם על מציאות הנפש הזנה לפי שאם היה הפעל בהזנה חלק היסוד האישי אשר בנזון כמו שחבו הקדמונים הנה בפני שהאש יאכל כל הדברים אשר מדרכם שיפסידם האש הנה לא יהיה בכאן לנזון מזון יותר מיוחד מהמזון ויהיה הטרח בתקון המזון לבטלה אבל יהיה האדם נזון מן העצים כמו שיהיה נזון מהלחם הנפלא בתקונו וזה כלו מבוא' הכזב ולזה הוא מבואר שיש בכאן נפש זנה והיא תעכל הדברים באמצעות החום הטבעי ומפני זה היתה פעולת ההזנה משוערת ומוגבלת כמו שזכר הפילוסוף וראוי שתדע כי התורה תכוין בדבר אחד בעינו לתועלות רבות כמו שיתבאר לך ממצות השבת שזכרה בה התורה שתי לתועלות והנה התור' בזה העניין מתדמה לטבע שיעשה דבר אחד לתועלות רבות כמו שהתבאר בטבעיות. וארי זאת ההצעה נאמר כי כבר היו על השלחן י"ב חלות בשתי מערכות היו שש מהם לצד המערבי והוא לצד הארון ושש לצד המזרח והוא לצד שתי המזבחו' וזה להורות על ענין נפלא הוא מהגדולות שבפנות העיוניות והתוריות והוא שזה המציאות השפל יושפע לו מעולם הגלגלים מה שיעמיד הנמצאים אשר בו כשיגביר ההפך האחד פעם וההפך האחר פעם. ובזה האופן יהיו נשמרים המורכבים אשר בכאן הזמן האפשרי כמו שהתבאר בטבעיות ולזה אמנם יהיה באמצעו' הגלגל הנוטה שישי' הכוכב פעם לפאת צפון ופעם לפא' דרום והנה היות הכוכב לפאת צפון הוא סבה להויה והיותו לצד דרום וסבה להפסד כי אז הוא רחוק מחישוב ותמנע ופעולת בישו' המו שהתבאר זה כלו בטבעיות ומה שיובא בו יותר התקופות הארבע' המתחדשות מצד השמש הוא הצמח עד שכבר יראה לו בעת היות השמש במזלות הצפוניים מה שידמה לבחרו' ובימות הגשמים יראה לו מה שדימה לזקנה וזה לאו' כי אלו הדברים אשר בכאן יושפעו להם פעולות מהגרמים השמימיים וזה יודה כי המציאות כלו הוא נקשר קצו בקצת. ושהוא אחד במספר ולזה יהיה בהכרח האלוה אחד במספר ואם לא הונח הענין כן על זה האופן יהיה מתחייב שתהיה התחלה אחת לנמצאות השפלות והתחלה אחרת לגרמים השמימיי' כמו שיחשבו המאמיני' שיהיו שם שני אלוהות והנה שש החלות אשר הם לצד המערב שהיו שם הדברים המורים על ההויה והמציאות מורות על ששת המזלות הצפוניים. להורות כי הנזונים נעזרי' בפעולות הזנה בגרמים השמימיי' בזה האופן שזכרנו ובזה האופן גם כן תתמיד בהם ההויה וההפסד והנה היה באמצע שתי המערכו' לבונה זכה להקטיר לשם יעת' להורות כי השם יתע' הוא עליון על הגרמים השמימיים ומאתו נאצל להם זה הכח והנה היום פנים רבים לכל אחד מאלו החלות כי לאלו המזלות פנים רבי' מצד התחלפות ככביהם קצתם מקצת ומצד התחלפות הככבים הרצים אשר יהיו בהם ומצד התחלפות מקום הכוכב ברחב מהמזל ההוא אם לצד דרום אם לצד צפון וזה כלו מבוא' למי שעיין בדברינו בזה בחמישי מספר מלחמות השם ובזה האופן יושפעו מהככבים הרצים בהיותם במזלות פעולות רבות בדרך שיושלמו בזה כל הפעולות הצריכות להעמיד זה המציאות השפל ולפי שהגבוה שבכוכבי לכת הוא שבתאי והיה מערכת אלו החלות ביום השבת אשר המושל בו שבתאי והיה שם עד יום השבת הבא באופן ששבה הממשלה לכל אחד מככבי לכת והיה לכל אחד מהם יום אחד וזה להורות כי מפעולות אלו הככבים בהיותם במזלות הצפוניים והדרומיי' יושפע לנזוני' שמירת הכח על החזון וישלם בזה האופן ההויה וההפסד על הצד שיתבא' בטבעיו' והנה העירה התורה בזה בבעלי הנפש הזנה לפי שבהם יותר פעולות התקופות הארבע' ממה שיראה בזולתם מבעלי הנפש ועוד כי כשהתבאר שהנזונים צריכים בפעולותיהם אל הגרמים השמימיים התבאר שכל בעלי נפש אשר בכאן צריכים בפעולותיהם אל הגרמים השמימיי' כי הם כלם בעלי נפש זכה. והנה היו מדליקים המנורה בשמן זית זך כתית כדי שתהיה מאירה תמיד באופן אחד בזולת תמורה להורות על שהנפש המרגשת היא בעצמה תמיד בענין אחד ואף על פי שכבר תחלף בחוזק ובחולשה מפני התחלפו' כליה כאלו תאמר שהזקן לא יהיה ראותו שלם כראות הבחור מפני חולשת עין הזקן לא מפני חולשת הכח הרואה והנה היה אור המנורה לצד המערב רוצה לומר אור הנר האמצעי לפי שאצל המקום ההוא היה מה שיורה על ההויה ואצל המזבחות שהיו מורים על ההפסד לא היה מאיר הנר כי המקום ההוא מורה על ההפסד והעדר הצורה והנה תמצא גם כן במנורה מה שירה על שהגרמים השמימיים משגיחים בשמירת הכח ומהם תסודר הויתם והפסדם ולה היו בה שבעה נרות להורות על שכוכבי לכת משגיחים בשמירתם ובאה המצוה שיהיו מדליקין המנורה בערב ובבקר כי ביום יעלו ששה מזלות ובלילה יעלו ששה מזלות אחרי' ומזלות היום עוזרים אל ההויה ומזלות הלילה עוזרים אל הפסד כי ביום האחד יתחדשו ארבעה תקופות כמו שיתחדשו בשנה והענין בזה כמו העניין בלחם הפני' אלא שבלחם הפנים היה אורך זמן עמידתו מורה על שבעה כוכבי לכת ומספר החלות על י"ב המזלו' ובמנורה הענין בהפך כי אורך זמן העמידה מורה על פועל המזבלות הי"ב ושבעה נרותיה מורים על פעל שבעה ככבי לכת בב"ח ואולי היה הענין כן לפי שפועל התקופות השמשיות יותר נגלה בצמחים מפוקל התקופות היומיו' ומפועל כוכבי לכת ואולם כב"ח ימצא העניין בה בהפך. וזה מבואר מאד בעניינם ולהיות הגביעי' והכפתורים וההסתעפו' לסעפים מפועל הצמחים הנה היתה המנורה בזה התאר להורו' על שהנפש המרגשת לא תהיה כי אם לב"ח כי היא במדרגת השלמות והצורה לנפש הצומחת ואולם שההסתעפות הוא מפועל הצמחי' הוא מבואר אלא שבקצת מוגבל ובקצתם בלתי מוגבל ואולם בב"ח היה ההסתעפות אשר באבריו מוגבל לא ישתנה אם לא מהכרח החומר כמו שהתבאר בטבעיות. ואולם הפרחים הוא מבואר מעניינם שהם מפועל הצמחי' וכן הכפתורים כי הוא מה שיעשה בצמח קודם שיצא הפרח וממנו יצא הפרח והוא כדמות כפתור תקיף בו קלפה והיא בצורת ביצה ששני ראשיה חדין ובתוכו יתהוה הפרח ואחר הפתח קלפה ההיא ויציאת הפרח תשאר קלפה כדמו' גביע משוקד וזה כלו מבואר מענין הצמחים ואולם מספר הגביעים והכפתורים והפרחי' היה להעיד על ענין אחר נפלא. והוא שהנפש המרגשת תעזור לנפש המדברת להשיג המושכלות במה שתמציא לו מהמוחשו' וכבר ידעת כי מהמוחשו' נקח המושכלות אלא שקצתם תמצא בהם המושכל מכוסה בקלפות רבות ר"ל שכבר נתערבו בהם משיגי' פרטיי' רבים וקצם ימצא בהם מושכל המופשט בהרבה מאלו הקלפו' לפי שכבר הופשטו מהם הרבה מהמשיגי' הפרטיי' כמו שנזכר בספר החוש והמוחש וקצתם לא ימצ' בהם המושכל בכח. אבל הם יד להשגת המושכל כמו שהגביעים הם יד ללקיחת הפרחים הדבקים בהם והוא מבואר כי באמצעות החוש המשותף והדמיון והכח הזוכר ישלם לנו מהמוחשות השגת המושכלות וכבר יגיעו להם המוחשים באמצעות החושים שהם חמש והחושים היותר נכבדים שבהם ועוזרים יותר אל השגת המושכלות הם חוש השמע וחוש הראות והנה חוש הראות הוא יותר נכבד ויותר עוזר בזה מחוש השמע וכבר התבאר בביאורנו לספר שיר השירים אופן החכמה בהמשל מה שיקח השכל מהחושים להשגת ההקדמות הראשונות לרעיה כשושנים כי השושנים הם הפרי בכח וכן המוחשות המגיעות לאדם הם בכח הפרי שהו המושכל מהם ואולם המשיל השגות חוש המשוש והטעם הריח לגביעים שאינם הפרי בכח אבל הם יד ללקיחת מה שהוא הפרי בכח והמשיל השגת חוש השמע לכפתור שבו הפרח בכח והמשיל השגת חוש הראות לפרח שהוא הפרי בכח ולזה היה בכל קנה מאלו הקנים שלשה גביעים וכפתור ופרח והיו כלם מאירי' לצד הקנה האמצעי והקנה האמצעי מאיר לצד הכרובים כי הנפש המרגשת תכין לנפש המדברת המוחשות אשר יצטרכו לה להשגת המושכלות באמצעות החוש המשותף והדימיון והכח הזוכר ושאר הכחו' העוזר' לזה לפי מה שהתבאר בטבעיו' והנה היה הפרח אצל רגלי המנור' להורות על שהסתעפו' כחות הנפש המרגש אמנם כוון להכין לנפש המדברת מה שיעזור אותה להשגת המושכלות במה שתכין לו שבו המושכלות בכח והוא המכוון ראשונה ואחר זה הושם שם גביע וכפתור ופרח להורות שבאלו השלשה פנים ימצא מה שיוכן לנפש המדברת מהמוחשות באמצעות הנפש המרגשת להשיג המושכלות. וזה מבואר מאד למי שעיין בחכמת הנמצאות. ואולם הכפתור שיהיה במקו' יציאת הקנים הנה עם שהיה לגוי ולתת חוזק למנור' הנה הוא מרה על שהסתעפו' הנפש המרגשת לאלו הכחות היה מכוון לזה התכלית כי יגיעו המוחשו' מקצתם לקצת ויתנקו מהמשיגי' ההיולאניי' והקלופ' באופן שיקל לשכל להפשיט' מחומריהם ולזה היו הפרחי' בהם עם קליפתם במקום יציאת הקני' ובסוף הענין ימצ' בהם הפרח בזולת הקליפה והוא אצל המקום אשר יתנו ממנו אורם קצתם לקצת להורו' שבסוף הענין יתנקו מוחשות מהרבה מקלפותיהם באמצעות אלו הכחות וכבר התבאר שהענין הוא כן בספר החוש והמוחש. והנה היתה המנורה מחתיכה אחת במספ' עם רבוי חלקיה להורות על שהנפש המרגשת הא אחת ואע"פ שכחותיה רבים ולזאת הסבה בעינ' היתה בכללה מככר זהב כדי שישלם בה האחדות בכל הפני' שאפשר והנה היתה גובה המנורה כקומת אדם הבינוני שהוא ג' אמו' לפי שהוא מורה על ענין האד' ואפש' שככה היה גובה של הארון עם הכרובי' או יותר מעט בדרך שיהיו כנפיהם למעל מומת האד' הנה זה הוא מה שנראה לנו בענין הארון והשלחן והמנורה והוא נפלא מאד ומעיד לעצמו מכל צד ומכל פנה שזאת היתה הכונה בהם ואולם התועלת המגיע מהמשכן וחצר המשכן בהיותם בזה התאר הנזכר בזאת הפרשה הנה הוא מבואר עם מעט עיון מה שזכרנו במה שקדם. וזה כי במה שצוה לעשות יריעות שש משזר ותכלת וארגמן ותולעת שני מעשה חושב ושיהיו בהם צורות כרובי' העיר על שהאהל המקיף באלו הדברים השפלים אשר הורה עליהם מה שבתך המשכן והאם הגרמים השמימיים הם בעלי שכל. ולזה שם בהם צורת כרובים ובזה האופן הם משגיחים באלו הנמצאו' כמו שביארנו בה' מספר מ"י ובאו היריעו' מארבעה מינים מתחלפי' מפני שכבר יסתעפו מהם בזה נמצא השפל ארבע מינים מהצורות והם צורות המתדמים החלקים וצורות הצומחים וצורות הב"ח וצורת המדברים ולפי שאנחנו נדע שהם בעלי שכל מצד הפעולות המגיעות מהם בה נמצא השפל היו צורות הכרובים אשר בהם נראות מלמטה ומלמעלה אלא שהצורות הנראות מלמעלה היו מכוסות ביריעות עזים כי לא יתכן נשיג אלו הצורות מצד מהותם. אבל יראו מלמטה לבד מצד מה שישפע מהם ולפי שמספר אלו השכלים הראשון הוא עשרה והם השכל הפועל ושבעה לשבעה גלגלי כוכבי לכת ואחד לגלגלי המזלות והעשירי הוא קדש שהוא השם יתע' הנה מפני זה היו מספר היריעות אשר בהם היו הכרובים עשרה והיה גובה הקרשי' עשרה אמות והיה רוחב קדש הקדשי' וארכו עשרה אמות כי הוא לבדו מעיד על מציאות השכל והיה אורך הפרוכת ורוחבי י' אמו' וזה כולו הוא להעיד כי אין השם יתע' אחד ממניעי הגרמים השמימיים כמו שחשבו קצת הפילוסופים אבל הם כלם עלולים ממנו. ולזאת ההערה היו המעשרות בכללם וכבר ביארנו במה שאין ספק בו שהענין הוא כן בה' ממ"י והנה לזאת הסבה בעינה היה בפרכת צורת הכרובים והנה היתה הפרכת בזה האופן כדי שיהיה קדש הקדשים מוקף מכל צדדיו מזה המקיף אשר בו צורת כרובים לפי שפועל הכרובים בזה העולם השפל הוא בשני פנים האחד הוא בהוית הצורות והשני הוא בהגעת המושכלו' על צד ההשפעה והאדם לבדו הוא אשר יקבל מהם זה השפע לשני ולזה היה מוקף מקום קדש קדשי' המורה על הצורה האנושית מזה המקיף אשר בו צורת כרובים מכל הצדדים והנה התדבקו עשר יריעות בחמשי' קרסים להורות כי מספר אלו השכלים הם חמשים כשימנו העלות והעלולים האחרונים. וזה שבכאן מח' גלגלים לפי מה שביארנו במה שאין ספק בו בה' ממ"י ולכל אחד מהם מגיע הוא שכל כמו שהתבאר שם וכאשר יחובר להם השכל הפועל. והשם יתע' היה המספר חמשים וזה גם כן להעיד על שאין השם יתע' אחד ממגיעי הגרמי' השמימיים וזה סבת היובל לקדש שנת החמישים שנה. וזה סוד חג השבועות לקדש יום החמישים. וראוי שתדע שזה אמנם יהיה כן אם לא הונחה לתנועת הנטייה גלגל נוסף אמנם כשהונח לתנועת הנטייה גלגל נוסף כמו שיראה חיובו ממה שנתבאר בחמישי ממלחמות השם הנה יהיה מספר השכלים זולת זה המספר שזכרנו ותהיה ההערה בזה לזה הענין בעינו והוא כל אחד מאלו מחובר משבעה שבועות שהם מ"ט ומאחד שהוא קדש וזה מבואר ביובל ובחג השבועות. והנה היה קדוש השבעיו' לסבה שזכרנו בזה במה שקדם וקדוש האחד אחר שבעה שבעיות היה להעיד בשבעה כוכבי לכת עם רבוי הגלגלים המניעין אותם שהם כלם עלולים מהסבה אחת עליונה והוא השם יתע' כי לא יתכן שישלם מכלם מציאות אחר והוא זה העולם השפל אם לא היו כלן עלולים מסבה אחת במספר כמו שביארנו בחמישי מספר מלחמות השם. והנה התבארו בזה המקום שני דרושים נפלאים האחד הוא שאין השם יתע' ממניעי הגרמים השמימיים והשני שהשם יתע' אינו השכל הפועל וכבר הארכנו בזאת החקירה בחמישי מספר מלחמות השם והנה היו אל הקרסים מזהב וכל מה שהיה במשכן להורות על הכבוד והקיום כי הצורות בכללם אין להם הפסד בעצמותם ואמנם החומר הוא סבת ההפסד כמו שהתבאר בטבעיות ואולם שהזהב הוא רב הקיום הנה זה מבואר מענינו עד שכבר העידו בו שהוא יעמוד אלפים מהשנים תחת הקרקע מזולת הפסד כלל והנה היו הקרסים אר יחוברו בהם יריעות העזים מנחשת לפי הם בלתי מכונים בעצמם אבל הם משמשים ליריעות האהל התחתונות וכבר מרה התרה במאמר הכולל כי משמשי המשכן יהיו מנחשת שנאמ' לכל כלי המשכן בכל עבודתו וכל יתדותיו וכל יתדות החצר נחשת והנה היה מספרם חמשים לסבה שקדם זכרה והוא מבואר שהקרס החמשים ישים המשכן אחד ומדובק בשלמות. וכן השם יתע' ישים פועל מניעי הגרמים השמימיים אחד כי לא יבא מרבים פעול אחד במספר אם לא מפני שהם עלולים מאחד במספר כמו שביארנו בחמישי ממלחמות ה' והנה היו יריעות עזים עודפות על יריעות המשכן מכל צדדיהם כדי שישלם להם הכסוי בשלמו' עם שכבר היה זה לשמור יריעו' המשכן שלא יתלכלכו . ומכסה עורו' האלים ומכסה עורות התחשים היה לתוספ' שמירה לאהל שלא ישיגהו הפסד מצד הרוח והגשם עד שכבר ישלמו בזה שיהיה באהל ארבעה מינים והם יריעות המשכן ויריעות העזים ומכסה עורות האילים ומכסה עורות תחשים להעיד כי מאלו הגרמי' השמימיים יושפעו בכאן ארבעה מינים מצורות כמו שקדם. ולזאת הסבה היתה הפרוכת על ארבעה עמודים ואולם הבריחים והאדנים היו לתת קיום לבניין המשכן ואמנ' הסמך שיהיה לפתח האהל היה על חמשה עמודי' והיו האדנים מנחשת. לפי שהוא בין שתי המזבחות המורים על הפסד. וסבת ההפסד הוא הגשם והנה הגשמים הראשונים המורגשים הם חמשה היסודות הארבעה והגרם החמישי והוא הגרם השמימיי כי הוא גם כן סבת ההפסדים במקרה כמו שקדם ואפשר שיונח הגרם החמישי בזה המקום החומר הראשון כי הוא סיבת כל ההפסדים מצד קבול ההפכים והם האיכויות הראשונות הנמצאו' ליסודו' במה הם יסודות והנה לחסרון מעלת החומר היו האדנים מנחשת שהוא פחות וקל ההפסד וכבר נכפל מספר החמש בכל חצר המשכן וזה שגובה הקלעים היה חמש אמות וחציו העליון היה גבהו חמש אמות וכן חציו התחתון וחצר המשכן שהיה בו המזבח היו חמשים בחמשים שהם חמשה מהמעלה השנית כי העשרה הם כמו אחד ועשרים כמו שנים ולזה היה העשרה סוף המספרים והנה היו מנחשת כל אדני החצר וכסוי המזבח וכל כלי החצר להורו' על חסרון מה הורה עליו הנמצא בחצר והעדר הקיום ממנו והוא התחלה החומרית והנה היו במזבח ארבע קרנות והיו תוצאותם ממנו להורות על שהפסד המורכב יהיה מצד היסודו' אש' מהם הורכב וממנו יצאו בהפסדו וישוב אל יסוד ליסודו והנה המסך שהיה לשער החצר מארבעה מינים על ארבעה עמודים היה להעיד כי הכונה היתה בגשמים בעבור הצורה שהם ארבעה לאלו הנמצאות השפלות כי החומר הוא בלתי מכוון לעצמו:
